window.BraidData.sources["BraidCLI"] = {"module":"BraidCLI","files":[{"path":"Sources/BraidCLI/BraidCommand.swift","lines":36,"bytes":1435,"header":{"lines":[1,11],"what":[8,10],"pin":null,"in":null,"out":null},"marks":[],"first":1861,"scopes":[["S","BraidCommand",null,"",18,19,[19,42],36,null,-1,0],["f","run",[],"",28,28,[28,28],35,null,0,0]],"text":"//\n//  BraidCommand.swift\n//  BraidCLI\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The `braid` root command. Bare `braid` in a terminal opens the studio on the Braid\n//        screen (BRAID_NO_UI=1 prints help instead); everywhere else it prints help. Subcommands\n//        are the training and testing tools.\n//\n\nimport ArgumentParser\nimport BraidKit\nimport BraidStudio\nimport Foundation\n\n@main\nstruct BraidCommand: AsyncParsableCommand {\n    static let configuration = CommandConfiguration(\n        commandName: \"braid\",\n        abstract: \"The Braid Transformer: a braid of per-Thread Mamba2 strands under one reed, every token split exactly by the Thread that supplied it.\",\n        discussion: \"Bare `braid` in a terminal opens the studio (braid ui); BRAID_NO_UI=1 prints this help instead.\",\n        version: BraidVersion.string,\n        subcommands: [UICommand.self, DoctorCommand.self, InitCommand.self, ImportCommand.self, PackCommand.self, ThreadCommand.self, ClusterCommand.self, ChatCommand.self, VerifyCommand.self, CreditCommand.self, BenchCommand.self, ImportRaoLMCommand.self, AIICommand.self]\n    )\n\n    func run() async throws {\n        if Studio.isInteractive, ProcessInfo.processInfo.environment[\"BRAID_NO_UI\"] == nil {\n            let ui = try UICommand.parse([])\n            try await ui.run()\n            return\n        }\n        print(BraidCommand.helpMessage())\n    }\n}\n"},{"path":"Sources/BraidCLI/Commands/AII.swift","lines":119,"bytes":7047,"header":{"lines":[1,11],"what":[8,10],"pin":null,"in":null,"out":null},"marks":[],"first":1863,"scopes":[["S","AIICommand",null,"",17,17,[17,35],119,null,-1,0],["S","Status",null,"",21,21,[21,35],33,null,0,0],["f","run",[],"",23,23,[23,26],32,null,1,0],["S","Create",null,"",35,35,[35,35],56,null,0,0],["f","run",[],"",41,41,[41,26],55,null,3,0],["S","Start",null,"",58,58,[58,34],68,null,0,0],["f","run",[],"",61,61,[61,26],67,null,5,0],["S","Stop",null,"",70,70,[70,33],80,null,0,0],["f","run",[],"",73,73,[73,26],79,null,7,0],["S","Ingest",null,"",82,82,[82,35],104,null,0,0],["f","run",[],"",89,89,[89,26],103,null,9,0],["S","Wipe",null,"",106,106,[106,33],118,null,0,0],["f","run",[],"",110,110,[110,26],117,null,11,0]],"text":"//\n//  AII.swift\n//  BraidCLI\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid aii status|create|start|stop|ingest|wipe`: the machine's AII and the demo AIIs Braid\n//        creates under the repo's aii/ folder, and the Braid corpus in a lane (deposit a dataset\n//        node, remove it).\n//\n\nimport ArgumentParser\nimport BraidKit\nimport Foundation\n\nstruct AIICommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"aii\", abstract: \"The machine's AII, demo AIIs, and Braid's corpus in a lane.\",\n                                                    subcommands: [Status.self, Create.self, Start.self, Stop.self, Ingest.self, Wipe.self], defaultSubcommand: Status.self)\n\n    struct Status: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"status\", abstract: \"The machine's AII and every demo AII: home, lanes, Thread health.\")\n        func run() throws {\n            guarded {\n                let root = AIIDetect.demoRoot()\n                for name in [LaneAddress.machine] + AIIDetect.demos(demoRoot: root) {\n                    let report = try Blocking.run { await AIIDetect.status(aii: name, demoRoot: root) }\n                    let health = report.health.map { \"Thread \\($0.status) on \\(report.httpPort)/\\(report.grpcPort) (stack \\($0.stack ?? \"?\"), contract \\($0.contract ?? 0), embedder \\($0.embedderPhase ?? \"?\"))\" } ?? (report.problem ?? \"?\")\n                    print(\"\\(name.padding(toLength: 10, withPad: \" \", startingAt: 0)) \\(report.home.path)  lanes \\(report.lanes.joined(separator: \"/\"))  \\(health)\")\n                }\n            }\n        }\n    }\n\n    struct Create: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"create\", abstract: \"Provision a demo AII home (APFS) and start its Thread on free ports.\")\n        @Argument var name: String\n        @Option(help: \"The home's path (default: <repo>/aii/<name>).\") var at: String?\n        @Option(help: \"http,grpc ports (default: the first free pair of the plan 47181/47190, 47281/47290, …).\") var ports: String?\n        @Option(help: \"The AIIServer binary (default: BRAID_AII_SERVER or ~/.rao/aii/bin/AIIServer).\") var server: String?\n        func run() throws {\n            guarded {\n                var pair: (http: Int, grpc: Int)? = nil\n                if let ports {\n                    let parts = ports.split(separator: \",\").compactMap { Int($0) }\n                    guard parts.count == 2 else { throw BraidFailure.usage(\"--ports takes http,grpc\") }\n                    pair = (parts[0], parts[1])\n                }\n                let serverURL = (server ?? ProcessInfo.processInfo.environment[\"BRAID_AII_SERVER\"]).map { URL(fileURLWithPath: ($0 as NSString).expandingTildeInPath) }\n                let record = try DemoAII.create(name: name, demoRoot: AIIDetect.demoRoot(), at: at.map { URL(fileURLWithPath: ($0 as NSString).expandingTildeInPath, isDirectory: true) },\n                                                ports: pair, server: serverURL) { note(\"aii create: \\($0)\") }\n                print(\"\\(record.name)  \\(record.root)  http \\(record.httpPort)  grpc \\(record.grpcPort)\")\n                print(\"lanes: ambient, craft, veil — address a Thread as \\(record.name)/<lane>\")\n            }\n        }\n    }\n\n    struct Start: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"start\", abstract: \"Start (or adopt) a demo AII's Thread.\")\n        @Argument var name: String\n        func run() throws {\n            guarded {\n                let record = try DemoAII.record(name: name, demoRoot: AIIDetect.demoRoot())\n                try DemoAII.start(record: record) { note(\"aii start: \\($0)\") }\n                print(\"\\(name) up on \\(record.httpPort)/\\(record.grpcPort)\")\n            }\n        }\n    }\n\n    struct Stop: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"stop\", abstract: \"Stop a demo AII's Thread.\")\n        @Argument var name: String\n        func run() throws {\n            guarded {\n                let record = try DemoAII.record(name: name, demoRoot: AIIDetect.demoRoot())\n                try DemoAII.stop(record: record)\n                print(\"\\(name) stopped\")\n            }\n        }\n    }\n\n    struct Ingest: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"ingest\", abstract: \"Deposit a dataset node (or a folder) into a lane as Braid's corpus there.\")\n        @OptionGroup var workArea: WorkAreaOptions\n        @Argument(help: \"<aii>/<lane>, e.g. home/ambient or demo-a/craft\") var lane: String\n        @Option(help: \"dataset:<name or path>#<node> or dir:<path>\") var from: String\n        @Option var limit: Int?\n        @Option var batch: Int = 16\n        func run() throws {\n            guarded {\n                guard let address = LaneAddress(parsing: lane) else { throw BraidFailure.usage(\"lane addresses are <aii>/<lane>: home or a demo AII, and a lane registered on it\") }\n                let spec = try CorpusSourceSpec(parsing: from)\n                let area = try workArea.resolve()\n                if case .lane = spec { throw BraidFailure.usage(\"ingest takes a dataset or a folder, not a lane\") }\n                if case .app = spec { throw BraidFailure.usage(\"ingest takes a dataset or a folder, not an app's records\") }\n                let snapshot = try CorpusSources.read(spec, slug: address.lane.rawValue, limit: limit, datasetsRoot: DatasetsRoot.resolve(workArea: area.root),\n                                                      demoRoot: AIIDetect.demoRoot()).snapshot\n                note(\"ingest: \\(snapshot.documentCount) documents, \\(snapshot.partitionCount) partitions → \\(address)\")\n                try LaneSource.ingest(snapshot, into: address, demoRoot: AIIDetect.demoRoot(), batchSize: batch) { done, total in if done % 16 == 0 || done == total { note(\"ingest: \\(done)/\\(total)\") } }\n                let stats = try LaneSource.stats(address: address, demoRoot: AIIDetect.demoRoot())\n                print(\"\\(address): \\(snapshot.documentCount) documents deposited; the lane now holds \\(stats.documents) documents in \\(stats.groups) groups\")\n            }\n        }\n    }\n\n    struct Wipe: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"wipe\", abstract: \"Remove Braid's corpus from a lane (by exported ids; never an empty list).\")\n        @Argument var lane: String\n        @Flag var yes = false\n        func run() throws {\n            guarded {\n                guard let address = LaneAddress(parsing: lane) else { throw BraidFailure.usage(\"lane addresses are <aii>/<lane>\") }\n                guard yes else { throw BraidFailure.usage(\"pass --yes to remove Braid's documents from \\(address)\") }\n                let removed = try LaneSource.wipe(address: address, demoRoot: AIIDetect.demoRoot())\n                print(\"\\(address): removed \\(removed) documents\")\n            }\n        }\n    }\n}\n"},{"path":"Sources/BraidCLI/Commands/Bench.swift","lines":397,"bytes":22928,"header":{"lines":[1,15],"what":[8,14],"pin":null,"in":null,"out":null},"marks":[],"first":1876,"scopes":[["S","BenchCommand",null,"",21,21,[21,37],178,null,-1,0],["S","Options",null,"",27,27,[27,38],101,null,0,0],["v","threadNames",null,"",48,48,[48,35],50,null,1,0],["v","copyNames",null,"",52,52,[52,33],54,null,1,0],["f","copyBraid",["of"],"",57,57,[57,67],61,[56,56],1,0],["f","url",["_"],"",63,63,[63,40],63,null,1,8],["f","assemble",["commons"],"",66,66,[66,72],87,[65,65],1,0],["f","output",["bench","rescoring"],"",90,90,[90,67],94,[89,89],1,0],["f","write",["_","bench","rescoring"],"",96,96,[96,85],100,null,1,0],["S","Trace",null,"",103,103,[103,34],127,null,0,0],["f","run",[],"",108,108,[108,26],126,null,9,0],["S","Gaming",null,"",129,129,[129,35],151,null,0,0],["f","run",[],"",134,134,[134,26],150,null,11,0],["S","Lift",null,"",153,153,[153,33],177,null,0,0],["f","run",[],"",158,158,[158,26],176,null,13,0],["X","BenchCommand",null,"",180,180,[180,23],286,null,-1,0],["S","Stitched",null,"",181,181,[181,37],207,null,15,0],["f","run",[],"",188,188,[188,26],206,null,16,0],["S","Entropy",null,"",209,209,[209,36],233,null,15,0],["f","run",[],"",214,214,[214,26],232,null,18,0],["S","Question",null,"",235,235,[235,37],259,null,15,0],["f","run",[],"",240,240,[240,26],258,null,20,0],["S","Replacement",null,"",261,261,[261,40],285,null,15,0],["f","run",[],"",272,272,[272,26],284,null,22,0],["f","url",["_"],"",274,274,[274,48],274,null,23,12],["E","BenchTable",null,"",289,289,[289,16],397,[288,288],-1,0,[]],["f","header",["_","dataset","threads","createdAt"],"static",290,290,[290,101],294,null,25,0],["f","rules",["_"],"static",296,296,[296,44],299,null,25,0],["f","reported",["_"],"static",301,301,[301,52],308,null,25,0],["f","print",["_"],"static",310,310,[310,45],324,null,25,0],["f","print",["_"],"static",326,326,[326,46],336,null,25,0],["f","sessions",["_"],"static",338,338,[338,45],340,null,25,0],["f","print",["_"],"static",342,342,[342,48],351,null,25,0],["f","print",["_"],"static",353,353,[353,47],362,null,25,0],["f","print",["_"],"static",364,364,[364,48],373,null,25,0],["f","print",["_"],"static",375,375,[375,51],385,null,25,0],["f","print",["_"],"static",387,387,[387,44],396,null,25,0]],"text":"//\n//  Bench.swift\n//  BraidCLI\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid bench trace|gaming|lift|stitched|entropy|question --dataset <name>`: the acceptance\n//        benches on the braid in the work area (the commons and the named Threads on their live\n//        versions), each printing its rules table (id, verdict, the numbers), keeping its session logs\n//        and writing a JSON report; `--rescore <json>` re-applies the rules to a saved report without a\n//        model. `braid bench replacement` reads the A (κ 0) and B (κ > 0) reports and the verify\n//        reports of B's sessions and applies R1–R3. Rules are fixed before numbers; a bench never\n//        changes a default (`--module-gain` sets κ for one run only).\n//\n\nimport ArgumentParser\nimport BraidKit\nimport Foundation\n\nstruct BenchCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(\n        commandName: \"bench\",\n        abstract: \"The acceptance benches, rules fixed before numbers: trace (T1–T3), gaming (G1–G3), lift (L1–L4), stitched (S1–S3), entropy (E1–E3), question (Q1–Q5b), replacement (R1–R3), sweep-key (the key schemes).\",\n        subcommands: [Trace.self, Gaming.self, Lift.self, Stitched.self, Entropy.self, Question.self, Replacement.self, SweepKeyCommand.self])\n\n    struct Options: ParsableArguments {\n        @OptionGroup var workArea: WorkAreaOptions\n        @Option(help: \"The braid dataset the Threads were fed from (default: the dataset the first Thread's source names).\")\n        var dataset: String?\n        @Option(help: \"Comma-separated Thread names (default: braid.toml's [cluster] attach).\")\n        var threads: String?\n        @Option(help: \"Where to write the report (default: <work area>/bench/<bench>/<stamp>.json).\")\n        var report: String?\n        @Option(help: \"Re-apply the rules to a saved report instead of running the braid.\")\n        var rescore: String?\n        @Option(name: .customLong(\"per-node\"), help: \"Texts (trace) or prompts (gaming, lift facts) per Thread.\")\n        var perNode: Int?\n        @Option(help: \"The seed the shuffles draw from.\")\n        var seed: UInt64 = 42\n        @Flag(name: .customLong(\"no-commons\"), help: \"Leave the commons out (trace and gaming only; the gate then uses absolute evidence).\")\n        var noCommons = false\n        @Option(name: .customLong(\"module-gain\"), help: \"κ for this run: the trajectory module's weight in the gate's evidence (default: braid.toml's [gate] module_gain). Recorded in the report and the session header.\")\n        var moduleGain: Double?\n        @Option(help: \"Two Threads holding the same documents, comma-separated: G3 (gaming) and Q5b (question) run on a copy braid of the commons and these two.\")\n        var copy: String?\n\n        var threadNames: [String]? {\n            threads.map { $0.split(separator: \",\").map { String($0).trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty } }\n        }\n\n        var copyNames: [String]? {\n            copy.map { $0.split(separator: \",\").map { String($0).trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty } }\n        }\n\n        /// The copy braid `--copy` names, sharing the braid's loaded nodes.\n        func copyBraid(of braid: BenchBraid) throws -> BenchBraid? {\n            guard let names = copyNames else { return nil }\n            guard names.count == 2 else { throw BraidFailure.usage(\"--copy takes two Threads: a,b\") }\n            return try braid.subBraid(threads: names) { note(\"bench: \\($0)\") }\n        }\n\n        func url(_ path: String) -> URL { URL(fileURLWithPath: (path as NSString).expandingTildeInPath) }\n\n        /// The braid in the work area and the dataset world its Threads were fed from.\n        func assemble(commons: Bool) throws -> (BenchBraid, BenchWorld) {\n            let area = try workArea.resolve()\n            var config = try workArea.config(in: area)\n            if let moduleGain {\n                guard moduleGain >= 0 else { throw BraidFailure.usage(\"--module-gain is κ ≥ 0, not \\(moduleGain)\") }\n                config.gate.moduleGain = moduleGain\n                note(\"bench: κ \\(moduleGain) for this run (braid.toml unchanged)\")\n            }\n            guard let packRecord = config.pack, let pack = try Packs.find(packRecord.sha256, in: area) else { throw BraidFailure.missing(\"braid.toml names no pack that is on disk\") }\n            let names = (threadNames ?? config.attach).filter { !$0.isEmpty }\n            guard let first = names.first else { throw BraidFailure.usage(\"no Threads: pass --threads or create one\") }\n            var datasetName = dataset\n            if datasetName == nil, case .dataset(let nameOrPath, _)? = try? CorpusSourceSpec(parsing: try ThreadStore.info(area.thread(first)).source) {\n                datasetName = nameOrPath\n            }\n            guard let datasetName else { throw BraidFailure.usage(\"pass --dataset <name>: thread \\(first) was not fed from a dataset\") }\n            let directory = try DatasetsRoot.locate(datasetName, root: DatasetsRoot.resolve(workArea: area.root))\n            note(\"bench: loading dataset \\(directory.path)\")\n            let world = BenchWorld(dataset: try BraidDataset.load(directory))\n            let braid = try BenchBraid.assemble(area: area, config: config, pack: pack, threadNames: names, commons: commons) { note(\"bench: \\($0)\") }\n            return (braid, world)\n        }\n\n        /// Where the report goes: `--report`, else the work area's bench folder (a rescore without `--report` is only printed).\n        func output(bench: String, rescoring: Bool) throws -> URL? {\n            if let report { return url(report) }\n            if rescoring { return nil }\n            return BenchFormat.reportURL(area: try workArea.resolve(), bench: bench)\n        }\n\n        func write<T: Encodable>(_ report: T, bench: String, rescoring: Bool) throws {\n            guard let url = try output(bench: bench, rescoring: rescoring) else { return }\n            try JSONCoding.write(report, to: url)\n            print(\"report → \\(url.path)\")\n        }\n    }\n\n    struct Trace: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"trace\", abstract: \"T1–T3: the trace tells a Thread's own text from a pastiche of it; the holder's share of told and source answers under the live gate and the shadow β4 is reported.\")\n        @OptionGroup var options: Options\n\n        func run() throws {\n            guarded {\n                if let path = options.rescore {\n                    let report = TraceBench.rescore(try JSONCoding.read(TraceReport.self, from: options.url(path)))\n                    BenchTable.print(report)\n                    try options.write(report, bench: \"trace\", rescoring: true)\n                    return\n                }\n                let (braid, world) = try options.assemble(commons: !options.noCommons)\n                var sizes = BenchTextSizes()\n                if let perNode = options.perNode { sizes.perNode = perNode }\n                sizes.seed = options.seed\n                let started = Date()\n                let report = try TraceBench.run(braid: braid, world: world, sizes: sizes) { note(\"bench trace: \\($0)\") }\n                note(String(format: \"bench trace: %d texts in %.0f s\", report.texts.count, Date().timeIntervalSince(started)))\n                BenchTable.print(report)\n                try options.write(report, bench: \"trace\", rescoring: false)\n            }\n        }\n    }\n\n    struct Gaming: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"gaming\", abstract: \"G1–G3: on subjects nobody holds and generic prose every Thread stays open and the largest gate stays bounded; copies tie.\")\n        @OptionGroup var options: Options\n\n        func run() throws {\n            guarded {\n                if let path = options.rescore {\n                    let report = GamingBench.rescore(try JSONCoding.read(GamingReport.self, from: options.url(path)))\n                    BenchTable.print(report)\n                    try options.write(report, bench: \"gaming\", rescoring: true)\n                    return\n                }\n                let (braid, world) = try options.assemble(commons: !options.noCommons)\n                let copies = try options.copyBraid(of: braid)\n                let started = Date()\n                let report = try GamingBench.run(braid: braid, world: world, perNode: options.perNode ?? 10, copies: copies) { note(\"bench gaming: \\($0)\") }\n                note(String(format: \"bench gaming: %d prompts in %.0f s\", report.rows.count, Date().timeIntervalSince(started)))\n                BenchTable.print(report)\n                try options.write(report, bench: \"gaming\", rescoring: false)\n            }\n        }\n    }\n\n    struct Lift: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"lift\", abstract: \"L1–L4: the commons leads nobody's text, inherited knowledge is not attributed, the owner's lift carries its facts; held-out NLL against the commons alone reported.\")\n        @OptionGroup var options: Options\n\n        func run() throws {\n            guarded {\n                if let path = options.rescore {\n                    let report = LiftBench.rescore(try JSONCoding.read(LiftReport.self, from: options.url(path)))\n                    BenchTable.print(report)\n                    try options.write(report, bench: \"lift\", rescoring: true)\n                    return\n                }\n                if options.noCommons { throw BraidFailure.usage(\"bench lift needs the commons in the braid\") }\n                let (braid, world) = try options.assemble(commons: true)\n                var sizes = LiftBench.Sizes()\n                if let perNode = options.perNode { sizes.factsPerNode = perNode }\n                let started = Date()\n                let report = try LiftBench.run(braid: braid, world: world, sizes: sizes) { note(\"bench lift: \\($0)\") }\n                note(String(format: \"bench lift: %d prompts and texts in %.0f s\", report.rows.count, Date().timeIntervalSince(started)))\n                BenchTable.print(report)\n                try options.write(report, bench: \"lift\", rescoring: false)\n            }\n        }\n    }\n}\n\nextension BenchCommand {\n    struct Stitched: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"stitched\", abstract: \"S1–S3: the module's stitched signature fires on what a Thread trained on but did not index, and not on unseen, unrelated or indexed text.\")\n        @OptionGroup var options: Options\n        @Option(name: .customLong(\"withheld\"), help: \"The Thread that withholds documents from its index (default: the one in --threads that does).\")\n        var withheld: String?\n\n        func run() throws {\n            guarded {\n                if let path = options.rescore {\n                    let report = StitchedBench.rescore(try JSONCoding.read(StitchedReport.self, from: options.url(path)))\n                    BenchTable.print(report)\n                    try options.write(report, bench: \"stitched\", rescoring: true)\n                    return\n                }\n                let (braid, world) = try options.assemble(commons: true)\n                var sizes = StitchedSizes()\n                if let perNode = options.perNode { sizes.perNode = perNode }\n                sizes.seed = options.seed\n                let started = Date()\n                let report = try StitchedBench.run(braid: braid, world: world, sizes: sizes, thread: withheld) { note(\"bench stitched: \\($0)\") }\n                note(String(format: \"bench stitched: %d texts in %.0f s\", report.texts.count, Date().timeIntervalSince(started)))\n                BenchTable.print(report)\n                try options.write(report, bench: \"stitched\", rescoring: false)\n            }\n        }\n    }\n\n    struct Entropy: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"entropy\", abstract: \"E1–E3: the entropy path's coherent runs against the trace on the trace bench's texts.\")\n        @OptionGroup var options: Options\n\n        func run() throws {\n            guarded {\n                if let path = options.rescore {\n                    let report = EntropyBench.rescore(try JSONCoding.read(EntropyReport.self, from: options.url(path)))\n                    BenchTable.print(report)\n                    try options.write(report, bench: \"entropy\", rescoring: true)\n                    return\n                }\n                let (braid, world) = try options.assemble(commons: true)\n                var sizes = BenchTextSizes()\n                if let perNode = options.perNode { sizes.perNode = perNode }\n                sizes.seed = options.seed\n                let started = Date()\n                let report = try EntropyBench.run(braid: braid, world: world, sizes: sizes) { note(\"bench entropy: \\($0)\") }\n                note(String(format: \"bench entropy: %d texts in %.0f s\", report.texts.count, Date().timeIntervalSince(started)))\n                BenchTable.print(report)\n                try options.write(report, bench: \"entropy\", rescoring: false)\n            }\n        }\n    }\n\n    struct Question: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"question\", abstract: \"Q1–Q5b: questions through the path braid chat uses, against the stored stem, the corpus slice and a paraphrase; retold and copied facts.\")\n        @OptionGroup var options: Options\n\n        func run() throws {\n            guarded {\n                if let path = options.rescore {\n                    let report = QuestionBench.rescore(try JSONCoding.read(QuestionReport.self, from: options.url(path)))\n                    BenchTable.print(report)\n                    try options.write(report, bench: \"question\", rescoring: true)\n                    return\n                }\n                let (braid, world) = try options.assemble(commons: true)\n                let copies = try options.copyBraid(of: braid)\n                var sizes = QuestionBench.Sizes()\n                if let perNode = options.perNode { sizes.perNode = perNode }\n                let started = Date()\n                let report = try QuestionBench.run(braid: braid, world: world, sizes: sizes, copies: copies) { note(\"bench question: \\($0)\") }\n                note(String(format: \"bench question: %d rows in %.0f s\", report.rows.count, Date().timeIntervalSince(started)))\n                BenchTable.print(report)\n                try options.write(report, bench: \"question\", rescoring: false)\n            }\n        }\n    }\n\n    struct Replacement: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"replacement\", abstract: \"R1–R3, the owner's replacement criterion: sessions A (κ 0, shadow β4 logged) against B (κ > 0) from saved trace and gaming reports and B's verify reports. Reads only; deletes nothing.\")\n        @OptionGroup var workArea: WorkAreaOptions\n        @Option(name: .customLong(\"trace-a\")) var traceA: String\n        @Option(name: .customLong(\"trace-b\")) var traceB: String\n        @Option(name: .customLong(\"gaming-a\")) var gamingA: String\n        @Option(name: .customLong(\"gaming-b\")) var gamingB: String\n        @Option(help: \"Where to write the report (default: <work area>/bench/replacement/<stamp>.json).\")\n        var report: String?\n\n        func run() throws {\n            guarded {\n                func url(_ path: String) -> URL { URL(fileURLWithPath: (path as NSString).expandingTildeInPath) }\n                let made = ReplacementBench.run(\n                    traceA: try JSONCoding.read(TraceReport.self, from: url(traceA)), traceB: try JSONCoding.read(TraceReport.self, from: url(traceB)),\n                    gamingA: try JSONCoding.read(GamingReport.self, from: url(gamingA)), gamingB: try JSONCoding.read(GamingReport.self, from: url(gamingB)),\n                    inputs: [\"trace A\": url(traceA).path, \"trace B\": url(traceB).path, \"gaming A\": url(gamingA).path, \"gaming B\": url(gamingB).path])\n                BenchTable.print(made)\n                let out = try report.map(url) ?? BenchFormat.reportURL(area: workArea.resolve(), bench: \"replacement\")\n                try JSONCoding.write(made, to: out)\n                print(\"report → \\(out.path)\")\n            }\n        }\n    }\n}\n\n/// The rules table every bench prints: id, verdict, the numbers; then what is reported without a threshold.\nenum BenchTable {\n    static func header(_ bench: String, dataset: String, threads: [String: String], createdAt: Date) {\n        let formatter = ISO8601DateFormatter()\n        Swift.print(\"bench \\(bench) · \\(dataset) · \\(formatter.string(from: createdAt))\")\n        for (name, record) in threads.sorted(by: { $0.key < $1.key }) { Swift.print(\"  \\(name.padding(toLength: 12, withPad: \" \", startingAt: 0)) \\(record)\") }\n    }\n\n    static func rules(_ rules: [BenchRule]) {\n        let width = max(40, rules.map(\\.id.count).max() ?? 0)\n        for rule in rules { Swift.print(\"  \\(rule.id.padding(toLength: width, withPad: \" \", startingAt: 0)) \\(rule.verdict)  \\(rule.detail)\") }\n    }\n\n    static func reported(_ values: [String: Float]) {\n        guard !values.isEmpty else { return }\n        Swift.print(\"  reported (no threshold):\")\n        for (key, value) in values.sorted(by: { $0.key < $1.key }) {\n            // Small differences (R1's is a few parts in 10⁵) would print as 0.000.\n            Swift.print(\"    \\(key): \\(value != 0 && abs(value) < 0.001 ? String(format: \"%.2e\", value) : String(format: \"%.3f\", value))\")\n        }\n    }\n\n    static func print(_ report: TraceReport) {\n        header(\"trace\", dataset: report.dataset, threads: report.threads, createdAt: report.createdAt)\n        var census: [String] = []\n        for kind in BenchTextKind.allCases { census.append(\"\\(kind.rawValue) \\(report.texts.filter { $0.kind == kind }.count)\") }\n        Swift.print(\"  texts: \\(census.joined(separator: \" · \")) · values from token \\(report.from)\")\n        Swift.print(\"  κ \\(report.gate.map { \"\\($0.moduleGain)\" } ?? \"?\") (the module's weight in the gate)\")\n        rules(report.rules)\n        Swift.print(\"  arms (share of answer tokens, no threshold):\")\n        for arm in report.arms {\n            Swift.print(\"    \\(arm.set.padding(toLength: 22, withPad: \" \", startingAt: 0)) live gate \\(BenchFormat.num(arm.live))  shadow β4 \\(BenchFormat.num(arm.shadow))  (\\(arm.texts) texts, \\(arm.answerTokens) tokens)\")\n        }\n        reported(report.reported)\n        sessions(report.sessions)\n        Swift.print(\"  \\(report.summary)\")\n    }\n\n    static func print(_ report: GamingReport) {\n        header(\"gaming\", dataset: report.dataset, threads: report.threads, createdAt: report.createdAt)\n        var census: [String] = []\n        for set in GamingSet.allCases { census.append(\"\\(set.rawValue) \\(report.rows.filter { $0.set == set }.count)\") }\n        Swift.print(\"  prompts: \\(census.joined(separator: \" · \")) · \\(GamingBench.generated) tokens generated · κ \\(report.gate.moduleGain)\\(report.copyPair.map { \" · copies \" + $0.joined(separator: \" = \") } ?? \"\")\")\n        rules(report.rules)\n        reported(report.reported)\n        for note in report.notes ?? [] { Swift.print(\"  note: \\(note)\") }\n        sessions(report.sessions)\n        Swift.print(\"  \\(report.summary)\")\n    }\n\n    static func sessions(_ paths: [String]?) {\n        for path in paths ?? [] { Swift.print(\"  session: \\(path)\") }\n    }\n\n    static func print(_ report: StitchedReport) {\n        header(\"stitched\", dataset: report.dataset, threads: report.threads, createdAt: report.createdAt)\n        var census: [String] = []\n        for set in StitchedSet.allCases { census.append(\"\\(set.rawValue) \\(report.texts.filter { $0.set == set }.count)\") }\n        Swift.print(\"  \\(report.withheldThread) withholds \\(report.withheld.count) documents · texts: \\(census.joined(separator: \" · \")) · values from token \\(report.from)\")\n        rules(report.rules)\n        reported(report.reported)\n        sessions(report.sessions)\n        Swift.print(\"  \\(report.summary)\")\n    }\n\n    static func print(_ report: EntropyReport) {\n        header(\"entropy\", dataset: report.dataset, threads: report.threads, createdAt: report.createdAt)\n        var census: [String] = []\n        for kind in BenchTextKind.allCases { census.append(\"\\(kind.rawValue) \\(report.texts.filter { $0.kind == kind }.count)\") }\n        Swift.print(\"  texts: \\(census.joined(separator: \" · \")) · coherent: H_knn ≤ \\(String(format: \"%.3f\", report.module.coherent)) for \\(report.module.coherentRun) positions · in trace: chain ≥ \\(report.phrase)\")\n        rules(report.rules)\n        reported(report.reported)\n        sessions(report.sessions)\n        Swift.print(\"  \\(report.summary)\")\n    }\n\n    static func print(_ report: QuestionReport) {\n        header(\"question\", dataset: report.dataset, threads: report.threads, createdAt: report.createdAt)\n        var census: [String] = []\n        for set in QuestionSet.allCases { census.append(\"\\(set.rawValue) \\(report.rows.filter { $0.set == set }.count)\") }\n        Swift.print(\"  rows (sets × arms): \\(census.joined(separator: \" · \"))\\(report.copyPair.map { \" · copies \" + $0.joined(separator: \" = \") } ?? \"\")\")\n        rules(report.rules)\n        reported(report.reported)\n        sessions(report.sessions)\n        Swift.print(\"  \\(report.summary)\")\n    }\n\n    static func print(_ report: ReplacementReport) {\n        Swift.print(\"bench replacement · κ A \\(report.moduleGainA.map { \"\\($0)\" } ?? \"?\") · κ B \\(report.moduleGainB.map { \"\\($0)\" } ?? \"?\")\")\n        for (name, path) in report.inputs.sorted(by: { $0.key < $1.key }) { Swift.print(\"  \\(name): \\(path)\") }\n        for session in report.sessions {\n            let issues = session.issues.isEmpty ? \"no issues\" : session.issues.sorted { $0.key < $1.key }.map { \"\\($0.key) \\($0.value)\" }.joined(separator: \", \")\n            Swift.print(\"  verify \\(URL(fileURLWithPath: session.session).lastPathComponent): \\(session.verified ? (session.status ?? \"?\") + \", \" + issues : \"no verify report\")\")\n        }\n        rules(report.rules)\n        reported(report.reported)\n        Swift.print(\"  \\(report.summary)\")\n    }\n\n    static func print(_ report: LiftReport) {\n        header(\"lift\", dataset: report.dataset, threads: report.threads, createdAt: report.createdAt)\n        var census: [String] = []\n        for set in LiftSet.allCases { census.append(\"\\(set.rawValue) \\(report.rows.filter { $0.set == set }.count)\") }\n        Swift.print(\"  prompts and texts: \\(census.joined(separator: \" · \"))\")\n        rules(report.rules)\n        reported(report.reported)\n        sessions(report.sessions)\n        Swift.print(\"  \\(report.summary)\")\n    }\n}\n"},{"path":"Sources/BraidCLI/Commands/Chat.swift","lines":105,"bytes":6424,"header":{"lines":[1,14],"what":[8,13],"pin":null,"in":null,"out":null},"marks":[],"first":1913,"scopes":[["S","ChatCommand",null,"",20,20,[20,41],105,null,-1,0],["f","run",[],"",31,31,[31,28],104,null,0,0]],"text":"//\n//  Chat.swift\n//  BraidCLI\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid chat \"<prompt>\"`: one headless turn of the braid, printing the per-token block the\n//        studio shows. A prompt ending in \"?\" is a question: the commons rewrites it into a stem,\n//        each Thread finds in its own index the sentence before the stem's best match and completes\n//        the stem behind it, and the answer stops at the sentence's end. Any other prompt is completed\n//        as written. Every turn is logged as a session; --json prints the session's lines instead.\n//        Without a prompt, the studio opens (the GUI).\n//\n\nimport ArgumentParser\nimport BraidKit\nimport Foundation\n\nstruct ChatCommand: AsyncParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"chat\", abstract: \"One turn of the braid: a completion, or a question (ending in ?) answered through the stem adapter and per-Thread context.\")\n    @OptionGroup var workArea: WorkAreaOptions\n    @Argument(help: \"The prompt; a trailing ? makes it a question. Omit it to open the studio.\") var prompt: String?\n    @Option(help: \"Comma-separated Thread names (default: braid.toml's [cluster] attach).\") var threads: String?\n    @Flag(name: .customLong(\"no-question\"), help: \"Complete the prompt as written even when it ends in ?.\") var noQuestion = false\n    @Option var lambda: Float = 0.5\n    @Option(name: .customLong(\"max-tokens\")) var maxTokens: Int = 24\n    @Option(help: \"0 = likeliest token; above 0 samples.\") var temperature: Float = 0\n    @Flag(help: \"Print the session's JSONL lines instead of the token block.\") var json = false\n\n    func run() async throws {\n        guard let prompt, !prompt.trimmingCharacters(in: .whitespaces).isEmpty else {\n            // No prompt: the studio, as bare `braid`.\n            var ui = try UICommand.parse([])\n            ui.workArea = workArea\n            try await ui.run()\n            return\n        }\n        guarded {\n            let area = try workArea.resolve()\n            let config = try workArea.config(in: area)\n            guard let packRecord = config.pack, let pack = try Packs.find(packRecord.sha256, in: area) else { throw BraidFailure.missing(\"braid.toml names no pack that is on disk\") }\n            let names = (threads.map { $0.split(separator: \",\").map { String($0).trimmingCharacters(in: .whitespaces) } } ?? config.attach).filter { !$0.isEmpty }\n            guard !names.isEmpty else { throw BraidFailure.usage(\"no Threads: pass --threads or create one\") }\n            let tokenizer = try BraidTokenizer(folder: pack.tokenizerFolder)\n            let reed = pack.reed(tokens: tokenizer.vocabSize)\n            var settings = ClusterSettings()\n            settings.gate = config.gate\n            settings.k = config.index.k\n            let cluster = Cluster(reed: reed, tokenizer: tokenizer, pack: pack.identity, settings: settings)\n            let scheme = KeyScheme(parsing: packRecord.keyScheme) ?? .residual(afterBlocks: pack.config.tapAfterBlocks)\n            let commons = try ThreadStore.commons(pack: pack, scheme: scheme)\n            try cluster.attach(commons)\n            var nodes: [String: LocalNode] = [:]\n            for name in names {\n                let loaded = try ThreadStore.load(name, in: area, pack: pack, commons: commons, tau: Float(config.index.tau))\n                nodes[name] = loaded.node\n                try cluster.attach(loaded.node)\n            }\n            let isQuestion = !noQuestion && prompt.trimmingCharacters(in: .whitespaces).hasSuffix(\"?\")\n            let turn: QuestionTurn\n            if isQuestion {\n                // The question path the bench measures: the commons' stem, each Thread's own context.\n                turn = try QuestionPath.prepare(question: prompt, adapter: QuestionAdapter(trunk: commons.trunk, reed: reed, tokenizer: tokenizer),\n                                                nodes: names.compactMap { name in nodes[name].map { (name: name, node: $0) } }, tokenizer: tokenizer,\n                                                k: config.index.k, rewriteTokens: maxTokens)\n                if !json {\n                    print(\"Q  \\(prompt)\")\n                    if let rewrite = turn.rewrite { print(\"▸  \\(rewrite.stem)   (\\(rewrite.rewriter), \\(String(format: \"%.0f\", rewrite.seconds * 1000)) ms)\") }\n                    for name in names {\n                        if let found = turn.contexts[name] {\n                            print(\"   \\(name): context \\(tokenizer.decode(found.tokens).debugDescription) (cos \\(String(format: \"%.2f\", found.score)), \\(found.documentID.suffix(12)))\")\n                        } else {\n                            print(\"   \\(name): no context (bare stem)\")\n                        }\n                    }\n                }\n            } else {\n                turn = QuestionTurn(question: prompt, rewrite: nil, stem: prompt, tokens: tokenizer.encode(\" \" + prompt), subject: nil, contexts: [:])\n            }\n            try FileManager.default.createDirectory(at: area.sessions, withIntermediateDirectories: true)\n            let logURL = area.sessions.appendingPathComponent(SessionLog.fileName(sessionID: cluster.sessionID))\n            try cluster.startLog(at: logURL)\n            var params = GenerationParameters()\n            params.lambda = lambda\n            params.maxTokens = maxTokens\n            params.temperature = temperature\n            params.tau = Float(config.index.tau)\n            params.k = config.index.k\n            let generation = isQuestion ? try QuestionPath.answer(turn, cluster: cluster, params: params)\n                : try cluster.generate(prompt: turn.prompt, params: params)\n            cluster.closeLog()\n            if json {\n                print(try String(contentsOf: logURL, encoding: .utf8), terminator: \"\")\n                return\n            }\n            TokenBlock.print(generation, cluster: cluster, tokenizer: tokenizer)\n            for decision in generation.decisions {\n                let followed = decision.followed ?? (decision.tied.isEmpty ? \"nobody (no chain advanced by the margin)\" : \"tie: \" + decision.tied.joined(separator: \", \"))\n                print(\"followed: \\(followed)  advances \\(decision.advances.map { \"\\($0.key) \\($0.value)\" }.sorted().joined(separator: \", \"))\")\n            }\n            note(\"chat: session \\(logURL.path)\")\n        }\n    }\n}\n"},{"path":"Sources/BraidCLI/Commands/Cluster.swift","lines":179,"bytes":11721,"header":{"lines":[1,12],"what":[8,11],"pin":null,"in":null,"out":null},"marks":[],"first":1915,"scopes":[["S","ClusterCommand",null,"",18,18,[18,39],124,null,-1,0],["S","Spawn",null,"",21,21,[21,34],123,null,0,0],["f","run",[],"",40,40,[40,26],122,null,1,0],["f","schedule",["_"],"",80,80,[80,75],88,null,2,4],["E","TokenBlock",null,"",126,126,[126,16],179,null,-1,0,[]],["f","f",["_","_"],"static",127,127,[127,59],127,null,4,8],["f","print",["_","cluster","tokenizer"],"static",131,131,[131,93],178,[129,130],4,0],["f","name",["_"],"",138,138,[138,42],138,null,6,12],["f","isCommons",["_"],"",139,139,[139,45],139,null,6,12]],"text":"//\n//  Cluster.swift\n//  BraidCLI\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid cluster spawn --threads a,b --prompt \"…\"`: the braid in this process — the commons\n//        and the named Threads under one reed — one generation, every token printed as the\n//        handoff's block (the chosen token, every strand's share, the trace, both entropies with\n//        their one-step deltas, the citation), the royalties, and the session log's path.\n//\n\nimport ArgumentParser\nimport BraidKit\nimport Foundation\n\nstruct ClusterCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"cluster\", abstract: \"The braid in this process.\", subcommands: [Spawn.self], defaultSubcommand: Spawn.self)\n\n    struct Spawn: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"spawn\", abstract: \"Assemble the named Threads and the commons, run one generation, log the session.\")\n        @OptionGroup var workArea: WorkAreaOptions\n        @Option(help: \"Comma-separated Thread names (default: braid.toml's [cluster] attach).\")\n        var threads: String?\n        @Option(help: \"The prompt to complete.\")\n        var prompt: String\n        @Option(name: .customLong(\"max-tokens\")) var maxTokens: Int = 24\n        @Option var lambda: Float = 0.5\n        @Option var temperature: Float = 0\n        @Flag(name: .customLong(\"no-commons\"), help: \"Leave the commons out (the gate then uses absolute evidence).\")\n        var noCommons = false\n        @Flag(help: \"Print the generation as JSON instead of the token blocks.\")\n        var json = false\n        @Option(help: \"Attach a Thread at a generated position: name@pos (repeatable). It catches up on the session and joins at the next token boundary.\")\n        var attach: [String] = []\n        @Option(help: \"Detach a Thread at a generated position: name@pos (repeatable).\")\n        var detach: [String] = []\n\n        func run() throws {\n            guarded {\n                let area = try workArea.resolve()\n                let config = try workArea.config(in: area)\n                guard let packRecord = config.pack, let pack = try Packs.find(packRecord.sha256, in: area) else { throw BraidFailure.missing(\"braid.toml names no pack that is on disk\") }\n                let names = (threads.map { $0.split(separator: \",\").map { String($0).trimmingCharacters(in: .whitespaces) } } ?? config.attach).filter { !$0.isEmpty }\n                guard !names.isEmpty else { throw BraidFailure.usage(\"no Threads: pass --threads or create one\") }\n                let tokenizer = try BraidTokenizer(folder: pack.tokenizerFolder)\n                let reed = pack.reed(tokens: tokenizer.vocabSize)\n                var settings = ClusterSettings()\n                settings.gate = config.gate\n                if noCommons { settings.gate.evidence = .absolute }\n                settings.k = config.index.k\n                let cluster = Cluster(reed: reed, tokenizer: tokenizer, pack: pack.identity, settings: settings)\n                let scheme = KeyScheme(parsing: packRecord.keyScheme) ?? .residual(afterBlocks: pack.config.tapAfterBlocks)\n                note(\"cluster: loading the commons\")\n                let commons = try ThreadStore.commons(pack: pack, scheme: scheme)\n                note(String(format: \"cluster: the commons' trunk %@ · blocks %d–%d, the embedding and norm_f · %.0f MB · run by every Thread\", String(commons.trunk.seamSHA256.prefix(12)),\n                            pack.config.cut, pack.config.numHiddenLayers - 1, Double(StorageMath(config: pack.config).trunkBytes) / 1_000_000))\n                if noCommons {\n                    note(\"cluster: the commons' strand is left out; its trunk still serves the Threads\")\n                } else {\n                    try cluster.attach(commons)\n                }\n                for name in names {\n                    note(\"cluster: loading \\(name) · its head, blocks 0–\\(pack.config.cut - 1), and its index\")\n                    let loaded = try ThreadStore.load(name, in: area, pack: pack, commons: commons, tau: Float(config.index.tau))\n                    try cluster.attach(loaded.node)\n                }\n                try FileManager.default.createDirectory(at: area.sessions, withIntermediateDirectories: true)\n                let logURL = area.sessions.appendingPathComponent(SessionLog.fileName(sessionID: cluster.sessionID))\n                try cluster.startLog(at: logURL)\n                var params = GenerationParameters()\n                params.lambda = lambda\n                params.maxTokens = maxTokens\n                params.temperature = temperature\n                params.tau = Float(config.index.tau)\n                params.k = config.index.k\n                let promptTokens = tokenizer.encode(prompt)\n                note(\"cluster: \\(cluster.strandNames.joined(separator: \", \")) · prompt \\(promptTokens.count) tokens\")\n                func schedule(_ specs: [String]) throws -> [Int: [String]] {\n                    var out: [Int: [String]] = [:]\n                    for spec in specs {\n                        let parts = spec.split(separator: \"@\")\n                        guard parts.count == 2, let at = Int(parts[1]) else { throw BraidFailure.usage(\"expected name@pos, got \\(spec)\") }\n                        out[at, default: []].append(String(parts[0]))\n                    }\n                    return out\n                }\n                let attachAt = try schedule(attach)\n                let detachAt = try schedule(detach)\n                cluster.onEvent = { event in\n                    switch event {\n                    case .attached(let name, let position, let caughtUp, let seconds): note(String(format: \"cluster: %@ attached at %d (caught up %d tokens in %.2f s)\", name, position, caughtUp, seconds))\n                    case .detached(let name, let position): note(\"cluster: \\(name) detached at \\(position)\")\n                    case .step: break\n                    }\n                }\n                var generated = 0\n                let started = Date()\n                let generation = try cluster.generate(prompt: GenerationPrompt(text: prompt, tokens: promptTokens), params: params) { step in\n                    guard step.source == .gen else { return }\n                    generated += 1\n                    for name in attachAt[generated] ?? [] {\n                        do {\n                            let thread = try ThreadStore.load(name, in: area, pack: pack, commons: commons, tau: Float(config.index.tau))\n                            try cluster.attach(thread.node)\n                        } catch { note(\"cluster: cannot attach \\(name): \\(error)\") }\n                    }\n                    for name in detachAt[generated] ?? [] {\n                        do { try cluster.detach(name) } catch { note(\"cluster: cannot detach \\(name): \\(error)\") }\n                    }\n                }\n                cluster.closeLog()\n                let seconds = Date().timeIntervalSince(started)\n                if json {\n                    print(String(decoding: try JSONCoding.prettyEncoder().encode(generation.steps), as: UTF8.self))\n                } else {\n                    TokenBlock.print(generation, cluster: cluster, tokenizer: tokenizer)\n                }\n                note(String(format: \"cluster: %d tokens in %.1f s (%.2f s/token) · session %@\", generation.generated.count, seconds, seconds / Double(max(generation.generated.count, 1)), logURL.path))\n            }\n        }\n    }\n}\n\nenum TokenBlock {\n    static func f(_ x: Float, _ digits: Int = 2) -> String { String(format: \"%.\\(digits)f\", x) }\n\n    /// The per-token block over the shared steps (context lines excluded), each step read through\n    /// the strands it was recorded with, then the royalties by Thread and by document.\n    static func print(_ generation: Generation, cluster: Cluster, tokenizer: any Tokenizing) {\n        Swift.print(\"> \\(generation.gen.prompt.text)▸\\(generation.text)\")\n        let sharedIndices = generation.steps.indices.filter { generation.steps[$0].source != .ctx }\n        var previous: (records: [ThreadRecord], slots: [StrandSlot])? = nil\n        for (k, index) in sharedIndices.enumerated() {\n            let step = generation.steps[index]\n            let slots = index < generation.slots.count ? generation.slots[index] : []\n            func name(_ t: Int) -> String { t < slots.count ? slots[t].name : \"strand \\(t)\" }\n            func isCommons(_ t: Int) -> Bool { t < slots.count && slots[t].commons }\n            guard let records = step.threads else { continue }\n            defer { previous = (records, slots) }\n            guard !step.isPrompt else { continue }\n            let ordered = records.indices.sorted { records[$0].share > records[$1].share }\n            guard let lead = ordered.first else { continue }\n            let others = ordered.dropFirst().map { \"\\(name($0)) \\(f(records[$0].share))\" }.joined(separator: \", \")\n            Swift.print(\"  token \\(step.text.debugDescription)  ← \\(name(lead))  share \\(f(records[lead].share))  (\\(others))   p \\(f(step.prob))\")\n            var line2 = \"                    \"\n            if let trace = records[lead].trace, trace.length >= TraceRule.standard.phrase, let row = trace.row, lead < slots.count {\n                let partition = cluster.partitions[Int(row) + slots[lead].rowOffset]\n                line2 += \"trace: in-doc \\(partition?.documentID.suffix(12) ?? \"#\\(row)\") L=\\(trace.length)\"\n            } else {\n                line2 += \"trace: off-trace L=\\(records[lead].trace?.length ?? 0)\"\n            }\n            let before = previous.flatMap { prior -> ThreadRecord? in\n                guard let t = prior.slots.firstIndex(where: { $0.name == name(lead) }), prior.records.indices.contains(t) else { return nil }\n                return prior.records[t]\n            }\n            line2 += \"  H_knn \\(before.map { f($0.hknn) + \"→\" } ?? \"\")\\(f(records[lead].hknn))\"\n            if let hlm = records[lead].hlm { line2 += \"  H_lm \\(before?.hlm.map { f($0) + \"→\" } ?? \"\")\\(f(hlm))\" }\n            if !isCommons(lead) { line2 += \"   (shadow β4: \\(name(lead)) \\(f(records[lead].shadowShare)))\" }\n            Swift.print(line2)\n            let annotation = k < generation.annotations.count ? generation.annotations[k] : nil\n            if let citation = annotation?.citations.first {\n                let span = annotation?.spanIndex.map { \" · span \\($0 + 1)\" } ?? \"\"\n                Swift.print(\"                    cited: \\(citation.address.documentID.suffix(16))/partition-\\(citation.address.partitionIndex)@\\(citation.address.tokenOffset)  conf \\(f(citation.confidence))\\(span)\")\n            } else if !isCommons(lead) {\n                Swift.print(\"                    uncited: no retrieved context predicted this token\")\n            }\n        }\n        Swift.print(\"royalties (generated tokens: \\(generation.royalties.generated))\")\n        for line in generation.royalties.strands {\n            Swift.print(\"  \\(line.name.padding(toLength: 12, withPad: \" \", startingAt: 0)) led \\(line.led)  share Σ \\(String(format: \"%.2f\", line.share))  credit·bits \\(String(format: \"%.1f\", line.credit))\")\n        }\n        for doc in generation.royalties.documents.prefix(5) {\n            Swift.print(\"  \\(doc.name)/\\(doc.documentID.suffix(16))  \\(doc.tokens) tokens  share Σ \\(String(format: \"%.2f\", doc.share))\")\n        }\n        if !generation.spans.isEmpty { Swift.print(\"spans: \\(generation.spans.map { \"\\($0.text.debugDescription) → \\($0.source.documentID.suffix(12)) p\\($0.source.partitionIndex)@\\($0.source.tokenOffset)\" }.joined(separator: \"; \"))\") }\n    }\n}\n"},{"path":"Sources/BraidCLI/Commands/Credit.swift","lines":80,"bytes":4877,"header":{"lines":[1,12],"what":[8,11],"pin":null,"in":null,"out":null},"marks":[],"first":1924,"scopes":[["S","CreditCommand",null,"",18,18,[18,38],80,null,-1,0],["S","GenerationCredit",null,"",23,23,[23,39],31,null,0,0],["S","ThreadCredit",null,"",32,32,[32,35],32,null,0,8],["S","DocumentCredit",null,"",33,33,[33,37],33,null,0,8],["S","Decision",null,"",34,34,[34,31],34,null,0,8],["f","run",[],"",36,36,[36,22],79,null,0,0]],"text":"//\n//  Credit.swift\n//  BraidCLI\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid credit <session.jsonl>`: the derived views of a logged session, never stored — per\n//        generation the credit (form tokens the commons', content tokens each strand's by its share,\n//        bits-weighted), the followed-credit decision per sentence, and the royalties by Thread and by\n//        cited document. Each step is read through the strands it was recorded with.\n//\n\nimport ArgumentParser\nimport BraidKit\nimport Foundation\n\nstruct CreditCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"credit\", abstract: \"Credit, followed-credit decisions and royalties derived from a session log.\")\n    @Argument(help: \"The session log (sessions/<stamp>-<id>.jsonl).\") var session: String\n    @Flag(help: \"Print the views as JSON.\") var json = false\n\n    struct GenerationCredit: Encodable {\n        var generationID: String\n        var prompt: String\n        var text: String\n        var generated: Int\n        var threads: [ThreadCredit]\n        var documents: [DocumentCredit]\n        var decisions: [Decision]\n    }\n    struct ThreadCredit: Encodable { var name: String; var commons: Bool; var led: Int; var share: Double; var creditBits: Double }\n    struct DocumentCredit: Encodable { var thread: String; var documentID: String; var tokens: Int; var share: Double }\n    struct Decision: Encodable { var sentence: String; var followed: String?; var tied: [String]; var documentID: String?; var advances: [String: Int] }\n\n    func run() throws {\n        guarded {\n            let url = URL(fileURLWithPath: (session as NSString).expandingTildeInPath)\n            let logged = try SessionReader.read(url)\n            var out: [GenerationCredit] = []\n            for generation in logged.generations {\n                let all = SessionReplay.slots(for: generation, session: logged)\n                let indices = generation.steps.indices.filter { generation.steps[$0].source != .ctx }\n                let shared = indices.map { generation.steps[$0] }\n                let slots = indices.map { all[$0] }\n                let partitions = Dictionary((generation.end?.partitions ?? []).map { ($0.row, $0) }, uniquingKeysWith: { first, _ in first })\n                var credits = Credit.assign(shared, slots: slots)\n                let decisions = FollowedCredit.apply(&credits, steps: shared, slots: slots, partitions: partitions)\n                let royalties = Royalties.view(steps: shared, credits: credits, slots: slots, partitions: partitions)\n                out.append(GenerationCredit(\n                    generationID: generation.gen.generationID, prompt: generation.gen.prompt.text, text: generation.end?.text ?? shared.filter { !$0.isPrompt }.map(\\.text).joined(),\n                    generated: royalties.generated,\n                    threads: royalties.strands.map { ThreadCredit(name: $0.name, commons: $0.commons, led: $0.led, share: $0.share, creditBits: $0.credit) },\n                    documents: royalties.documents.map { DocumentCredit(thread: $0.name, documentID: $0.documentID, tokens: $0.tokens, share: $0.share) },\n                    decisions: decisions.map { decision in\n                        let text = shared[decision.window.start ..< min(decision.window.end, shared.count)].map(\\.text).joined()\n                        return Decision(sentence: text, followed: decision.followed, tied: decision.tied, documentID: decision.documentID, advances: decision.advances)\n                    }))\n            }\n            if json {\n                print(String(decoding: try JSONCoding.prettyEncoder().encode(out), as: UTF8.self))\n                return\n            }\n            for generation in out {\n                print(\"> \\(generation.prompt)▸\\(generation.text)\")\n                print(\"  generated \\(generation.generated) · \\(generation.generationID)\")\n                for line in generation.threads {\n                    print(\"  \\(line.name.padding(toLength: 14, withPad: \" \", startingAt: 0)) led \\(line.led)  share Σ \\(String(format: \"%.2f\", line.share))  credit·bits \\(String(format: \"%.1f\", line.creditBits))\")\n                }\n                for document in generation.documents.prefix(8) {\n                    print(\"  \\(document.thread)/\\(document.documentID.suffix(16))  \\(document.tokens) tokens  share Σ \\(String(format: \"%.2f\", document.share))\")\n                }\n                for decision in generation.decisions {\n                    let who = decision.followed ?? (decision.tied.isEmpty ? \"nobody\" : \"tie: \" + decision.tied.joined(separator: \", \"))\n                    print(\"  sentence \\(decision.sentence.debugDescription): followed \\(who)\\(decision.documentID.map { \" (\\($0.suffix(12)))\" } ?? \"\")\")\n                }\n            }\n        }\n    }\n}\n"},{"path":"Sources/BraidCLI/Commands/Doctor.swift","lines":34,"bytes":1339,"header":{"lines":[1,12],"what":[8,11],"pin":null,"in":null,"out":null},"marks":[],"first":1930,"scopes":[["S","DoctorCommand",null,"",18,18,[18,38],34,null,-1,0],["f","run",[],"",23,23,[23,22],33,null,0,0]],"text":"//\n//  Doctor.swift\n//  BraidCLI\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid doctor`: the checks before anything else — the Metal library, the work area and its\n//        free space, braid.toml, the pack and its tokenizer, the machine's AII (home, secrets, lanes,\n//        Thread health). The checks live in BraidKit (DoctorChecks), shared with the studio's Doctor\n//        screen. A failed check says what is missing and the command exits 1.\n//\n\nimport ArgumentParser\nimport BraidKit\nimport Foundation\n\nstruct DoctorCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"doctor\", abstract: \"Check the setup: Metal library, work area, braid.toml, pack, tokenizer, AII.\")\n\n    @OptionGroup var workArea: WorkAreaOptions\n\n    func run() throws {\n        print(\"braid doctor\")\n        let options = workArea\n        let checks = try Blocking.run {\n            await DoctorChecks.run(area: Result { try options.resolve() }, config: { try options.config(in: $0) })\n        }\n        for check in checks { print(check.line) }\n        let failures = checks.filter { !$0.ok }.count\n        print(failures == 0 ? \"all checks passed\" : \"\\(failures) check(s) failed\")\n        if failures > 0 { throw ArgumentParser.ExitCode(ExitCode.doctor.rawValue) }\n    }\n}\n"},{"path":"Sources/BraidCLI/Commands/Import.swift","lines":188,"bytes":11074,"header":{"lines":[1,11],"what":[8,10],"pin":null,"in":null,"out":null},"marks":[],"first":1932,"scopes":[["S","ImportCommand",null,"",18,18,[18,38],45,null,-1,0],["f","run",[],"",35,35,[35,22],44,null,0,0],["E","Importer",null,"",47,47,[47,14],72,null,-1,0,[]],["f","run",["source","revision","name","cut","tapAfterBlocks","check","area"],"static",48,48,[48,164],71,null,2,0],["S","InitCommand",null,"",74,74,[74,36],131,null,-1,0],["f","run",[],"",85,85,[85,22],118,null,4,0],["f","measure",["pack","area"],"static",120,120,[120,59],130,null,4,0],["E","Packs",null,"",133,133,[133,11],150,null,-1,0,[]],["f","list",["in"],"static",135,135,[135,68],141,[134,134],7,0],["f","find",["_","in"],"static",144,144,[144,77],149,[143,143],7,0],["S","PackCommand",null,"",152,152,[152,36],188,null,-1,0],["S","PackList",null,"",155,155,[155,37],169,null,10,0],["f","run",[],"",158,158,[158,26],168,null,11,0],["S","PackShow",null,"",171,171,[171,37],187,null,10,0],["f","run",[],"",175,175,[175,26],186,null,13,0]],"text":"//\n//  Import.swift\n//  BraidCLI\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid import <hf-id | folder>`: a Hugging Face Mamba2 checkpoint becomes a pack under the\n//        work area's packs/, hashed at import. `braid init --base <pack | hf-id>` imports when given\n//        an id, validates the pack and writes braid.toml with the storage math printed.\n//\n\nimport ArgumentParser\nimport BraidKit\nimport Foundation\nimport MLX\n\nstruct ImportCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"import\", abstract: \"Convert a pretrained Mamba2 checkpoint into a Braid pack.\")\n\n    @OptionGroup var workArea: WorkAreaOptions\n    @Argument(help: \"A Hugging Face repo id (AntonV/mamba2-130m-hf) or a folder holding config.json, safetensors and tokenizer files.\")\n    var source: String\n    @Option(help: \"The revision (commit) to fetch; default: the repo's latest, recorded in pack.json.\")\n    var revision: String?\n    @Option(help: \"The pack's name (default: the repo's last path component).\")\n    var name: String?\n    @Option(help: \"The first block of the commons' trunk, the blocks every Thread runs behind its own (default: half the blocks).\")\n    var cut: Int?\n    @Option(name: .customLong(\"tap\"), help: \"The residual tap the default key reads, after this many blocks (default: the cut).\")\n    var tapAfterBlocks: Int?\n    @Flag(help: \"Run the trunk once after the import: a greedy sample and the held-out NLL, recorded in pack.json.\")\n    var check = false\n\n    func run() throws {\n        guarded {\n            let area = try workArea.resolve()\n            try area.prepare()\n            let imported = try Importer.run(source: source, revision: revision, name: name, cut: cut, tapAfterBlocks: tapAfterBlocks, check: check, area: area)\n            print(\"pack \\(imported.pack.info.name)  \\(imported.pack.sha256)\")\n            print(\"  \\(imported.directory.path)\")\n            for (label, value) in StorageMath(config: imported.pack.config).table() { print(\"  \\(label.padding(toLength: 30, withPad: \" \", startingAt: 0)) \\(value)\") }\n        }\n    }\n}\n\nenum Importer {\n    static func run(source: String, revision: String?, name: String?, cut: Int?, tapAfterBlocks: Int?, check: Bool, area: WorkArea) throws -> PackImporter.Imported {\n        let folder: URL\n        var origin = source\n        if FileManager.default.fileExists(atPath: (source as NSString).expandingTildeInPath + \"/config.json\") {\n            folder = URL(fileURLWithPath: (source as NSString).expandingTildeInPath, isDirectory: true)\n            origin = \"folder:\\(folder.path)\"\n        } else {\n            folder = try PackImporter.fetch(repo: source, revision: revision, modelsHome: area.modelsHome) { note(\"import: \\($0)\") }\n            origin = \"hub:\\(source)@\\(PackImporter.snapshotCommit(folder) ?? revision ?? \"main\")\"\n        }\n        let packName = name ?? source.split(separator: \"/\").last.map(String.init) ?? source\n        let imported = try PackImporter.importPack(folder: folder, name: packName, source: origin, cut: cut, tapAfterBlocks: tapAfterBlocks, into: area.packs) { note(\"import: \\($0)\") }\n        if check {\n            note(\"import: running the trunk once\")\n            let tokenizer = try BraidTokenizer(folder: imported.pack.tokenizerFolder)\n            let trunk = try Trunk(pack: imported.pack)\n            let reed = imported.pack.reed(tokens: tokenizer.vocabSize)\n            let (sample, nll) = try Sampler.sampleAndNLL(trunk: trunk, reed: reed, tokenizer: tokenizer)\n            try PackImporter.record(referenceNLL: nll, sample: sample, in: imported.directory)\n            print(\"  sample: \\(sample.replacingOccurrences(of: \"\\n\", with: \"⏎\"))\")\n            print(String(format: \"  held-out NLL: %.3f nats/token\", nll))\n        }\n        return imported\n    }\n}\n\nstruct InitCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"init\", abstract: \"Validate a pack and write braid.toml in the work area.\")\n\n    @OptionGroup var workArea: WorkAreaOptions\n    @Option(help: \"The pack: its sha256 (or 12-hex prefix), its name, or a Hugging Face repo id to import first (not needed for --measure on an existing braid.toml).\")\n    var base: String?\n    @Flag(help: \"Overwrite an existing braid.toml.\")\n    var force = false\n    @Flag(help: \"Time the trunk on this machine (forward tokens/s, one training step, peak memory) at B×L 4×512, 8×512, 4×1024, 8×1024 and chunks 256 and 128; with an existing braid.toml, only measure.\")\n    var measure = false\n\n    func run() throws {\n        guarded {\n            let area = try workArea.resolve()\n            try area.prepare()\n            if measure, FileManager.default.fileExists(atPath: area.configFile.path), !force {\n                let config = try workArea.config(in: area)\n                guard let record = config.pack, let pack = try Packs.find(record.sha256, in: area) else { throw BraidFailure.missing(\"braid.toml names no pack that is on disk\") }\n                try Self.measure(pack: pack, area: area)\n                return\n            }\n            if FileManager.default.fileExists(atPath: area.configFile.path), !force {\n                throw BraidFailure.exists(\"\\(area.configFile.path) exists\", hint: \"pass --force to rewrite it\")\n            }\n            guard let base else { throw BraidFailure.usage(\"braid init needs --base <pack or hf-id>\") }\n            let pack: Pack\n            if let found = try Packs.find(base, in: area) {\n                pack = found\n            } else {\n                note(\"init: no pack named \\(base) in \\(area.packs.path); importing\")\n                pack = try Importer.run(source: base, revision: nil, name: nil, cut: nil, tapAfterBlocks: nil, check: false, area: area).pack\n            }\n            let c = pack.config\n            var config = BraidConfig(pack: BraidConfig.Pack(name: pack.info.name, sha256: pack.sha256, vocabularySHA256: pack.info.vocabularySHA256,\n                                                            tokenizerSHA256: pack.info.tokenizerSHA256, hiddenSize: c.hiddenSize, layers: c.numHiddenLayers, heads: c.numHeads,\n                                                            headDim: c.headDim, stateSize: c.stateSize, convKernel: c.convKernel, vocabRows: c.vocabSize,\n                                                            vocabTokens: pack.info.tokenizerVocabSize, keyScheme: \"residual:\\(c.tapAfterBlocks)\"))\n            config.aiiHome = \"~/.rao\"\n            try config.save(to: area.configFile)\n            print(\"braid.toml → \\(area.configFile.path)  (sha256 \\(config.sha256.prefix(12)))\")\n            print(\"pack \\(pack.info.name)  \\(pack.sha256.prefix(12))  vocabulary \\(pack.info.vocabularySHA256.prefix(12))  tokenizer \\(pack.info.tokenizerSHA256.prefix(12))\")\n            for (label, value) in StorageMath(config: c).table() { print(\"  \\(label.padding(toLength: 30, withPad: \" \", startingAt: 0)) \\(value)\") }\n            if measure { try Self.measure(pack: pack, area: area) }\n        }\n    }\n\n    static func measure(pack: Pack, area: WorkArea) throws {\n        note(\"measure: pack \\(pack.info.name) \\(pack.sha256.prefix(12)); one MLX workload, nothing else should run\")\n        let report = try TrunkMeasure.run(pack: pack, vocabTokens: pack.info.tokenizerVocabSize) { note(\"measure: \\($0)\") }\n        let url = area.bench.appendingPathComponent(\"measure\", isDirectory: true).appendingPathComponent(\"\\(SessionLog.stamp()).json\")\n        try JSONCoding.write(report, to: url)\n        print(\"   B      L  chunk   forward tok/s   step s   peak GB\")\n        for row in report.rows {\n            print(String(format: \"%4d %6d %6d %15.0f %8.2f %9.1f\", row.batch, row.length, row.chunk, row.forwardTokensPerSecond, row.stepSeconds, row.peakGB))\n        }\n        note(\"measure: report → \\(url.path)\")\n    }\n}\n\nenum Packs {\n    /// Every pack directory under packs/ with its info.\n    static func list(in area: WorkArea) throws -> [(URL, PackInfo)] {\n        guard FileManager.default.fileExists(atPath: area.packs.path) else { return [] }\n        return try FileManager.default.contentsOfDirectory(at: area.packs, includingPropertiesForKeys: nil)\n            .filter { FileManager.default.fileExists(atPath: $0.appendingPathComponent(Pack.infoFile).path) }\n            .map { ($0, try JSONCoding.read(PackInfo.self, from: $0.appendingPathComponent(Pack.infoFile))) }\n            .sorted { $0.1.createdAt < $1.1.createdAt }\n    }\n\n    /// By sha256 (or prefix) or by name; nil when nothing matches.\n    static func find(_ reference: String, in area: WorkArea) throws -> Pack? {\n        for (directory, info) in try list(in: area) where info.sha256.hasPrefix(reference.lowercased()) || info.name == reference {\n            return try Pack.load(from: directory)\n        }\n        return nil\n    }\n}\n\nstruct PackCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"pack\", abstract: \"The packs in the work area.\", subcommands: [PackList.self, PackShow.self], defaultSubcommand: PackList.self)\n\n    struct PackList: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"list\", abstract: \"Every pack: name, sha256, shape, cut.\")\n        @OptionGroup var workArea: WorkAreaOptions\n        func run() throws {\n            guarded {\n                let area = try workArea.resolve()\n                let packs = try Packs.list(in: area)\n                if packs.isEmpty { print(\"no packs in \\(area.packs.path); run braid import <hf-id>\"); return }\n                for (_, info) in packs {\n                    let c = info.config\n                    print(\"\\(info.sha256.prefix(12))  \\(info.name.padding(toLength: 18, withPad: \" \", startingAt: 0))  \\(c.numHiddenLayers)×\\(c.hiddenSize) heads \\(c.numHeads)×\\(c.headDim) state \\(c.stateSize)  cut \\(c.cut)  vocab \\(info.tokenizerVocabSize)/\\(c.vocabSize)  \\(info.source)\")\n                }\n            }\n        }\n    }\n\n    struct PackShow: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"show\", abstract: \"One pack's record, hashes re-derived, and the split: a Thread node and the commons' trunk.\")\n        @OptionGroup var workArea: WorkAreaOptions\n        @Argument var reference: String\n        func run() throws {\n            guarded {\n                let area = try workArea.resolve()\n                guard let pack = try Packs.find(reference, in: area) else { throw BraidFailure.missing(\"no pack \\(reference) in \\(area.packs.path)\") }\n                let data = try JSONCoding.prettyEncoder().encode(pack.info)\n                print(String(decoding: data, as: UTF8.self))\n                print(\"hashes re-derived on load: ok\")\n                for (label, value) in StorageMath(config: pack.config).table() where label.hasPrefix(\"a Thread node\") || label.hasPrefix(\"the commons' trunk\") {\n                    print(\"  \\(label.padding(toLength: 30, withPad: \" \", startingAt: 0)) \\(value)\")\n                }\n            }\n        }\n    }\n}\n"},{"path":"Sources/BraidCLI/Commands/ImportRaoLM.swift","lines":213,"bytes":17186,"header":{"lines":[1,18],"what":[8,15],"pin":[16,17],"in":null,"out":null},"marks":[],"first":1947,"scopes":[["S","ImportRaoLMCommand",null,"",24,24,[24,43],213,null,-1,0],["f","run",[],"",40,40,[40,22],66,null,0,0],["f","runImport",["sets","dump","dataRoot","indexes","nodes","out","jobs"],"",69,69,[69,163],88,[68,68],0,0],["S","CheckReport",null,"",91,91,[91,34],100,[90,90],0,0],["f","runCheck",["sets","dump","index","dataRoot","indexes","nodes","out","jobs"],"",102,102,[103,46],208,null,0,0],["f","pad",["_","_"],"",210,210,[210,51],210,null,0,8],["f","sci",["_"],"",211,211,[211,40],211,null,0,8],["f","word",["_"],"",212,212,[212,40],212,null,0,8]],"text":"//\n//  ImportRaoLM.swift\n//  BraidCLI\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid import-raolm <dump>`: RaoLM's trajectory-bench records (a CitedGeneration per scored\n//        text, the base pass and each gate arm) become Braid session logs with `source: raolm`,\n//        under raolm-import/ in the work area by default, beside an import.json that says what was\n//        imported from where, how each field maps, and which `braid verify` checks such a log takes.\n//        `--check` validates the port against the same records instead and prints its table: (a)\n//        the shares from RaoLM's gate and probabilities, (b) Braid's tracker replaying RaoLM's chains\n//        over its index layouts, (c) phase A — T1–T3 from the dump's traces against RaoLM's own\n//        verdicts, and the regate under Braid's live gate against RaoLM's \"no agreement\" arm.\n//  PIN:  No model and no GPU. Reads the dump and RaoLM's node indexes; writes only under --out.\n//        Exit 0; 65 when a check fails.\n//\n\nimport ArgumentParser\nimport BraidKit\nimport Foundation\n\nstruct ImportRaoLMCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(\n        commandName: \"import-raolm\",\n        abstract: \"RaoLM trajectory-bench records → Braid session logs (source raolm); --check validates the port against them.\")\n\n    static let defaultOut = WorkArea.t9.appendingPathComponent(\"raolm-import\", isDirectory: true)\n\n    @Argument(help: \"The dump: index.json, a record per scored text, arms/<arm>/ (RaoLM's bench-trajectory --dump).\")\n    var dump: String\n    @Option(help: \"One set: base, or a gate arm by name (\\\"no agreement\\\") or directory (no-agreement). Default: the base pass and every complete arm.\")\n    var arm: String?\n    @Option(help: \"Where the logs and import.json (or check.json) go (default: /Volumes/T9/rao/projects/braid/raolm-import).\")\n    var out: String?\n    @Flag(help: \"Validate instead of importing: (a) shares, (b) the trace replay, (c) phase A; prints the table and writes check.json.\")\n    var check = false\n\n    func run() throws {\n        guarded {\n            let dumpURL = URL(fileURLWithPath: (dump as NSString).expandingTildeInPath, isDirectory: true)\n            let outURL = out.map { URL(fileURLWithPath: ($0 as NSString).expandingTildeInPath, isDirectory: true) } ?? Self.defaultOut\n            let index = try RaoLMDumpIndex.load(from: dumpURL)\n            let dataRoot = URL(fileURLWithPath: index.dataRoot, isDirectory: true)\n            let all = RaoLMPort.sets(dump: dumpURL, index: index)\n            for set in all where !set.complete { note(\"import-raolm: \\(set.name) is missing \\(set.missing.count) of \\(set.texts.count) records; left out\") }\n            let sets = try RaoLMPort.select(all, only: arm)\n            guard let first = sets.first?.texts.first else { throw BraidFailure.missing(\"no complete set in \\(dumpURL.path)\") }\n            // The node indexes, from the first record: every record must name the same.\n            let probe = try RaoLMGeneration.load(from: dumpURL.appendingPathComponent(sets[0].directory, isDirectory: true).appendingPathComponent(first.file))\n            guard let braid = probe.braid else { throw BraidFailure.data(\"\\(first.file) is not a braided generation\") }\n            note(\"import-raolm: loading RaoLM's node indexes under \\(dataRoot.path)\")\n            let indexes = try RaoLMPort.indexes(of: braid, dataRoot: dataRoot)\n            let nodes = RaoLMPort.nodeRecords(braid, indexes: indexes)\n            let jobs = max(1, min(6, ProcessInfo.processInfo.activeProcessorCount / 2))\n            let started = Date()\n            if check {\n                try runCheck(sets: sets, dump: dumpURL, index: index, dataRoot: dataRoot, indexes: indexes, nodes: nodes, out: outURL, jobs: jobs)\n            } else {\n                try runImport(sets: sets, dump: dumpURL, dataRoot: dataRoot, indexes: indexes, nodes: nodes, out: outURL, jobs: jobs)\n            }\n            fflush(stdout)\n            note(String(format: \"import-raolm: %.0f s\", Date().timeIntervalSince(started)))\n        }\n    }\n\n    /// Every record of every set written as a session log, then import.json.\n    func runImport(sets: [RaoLMPort.RecordSet], dump: URL, dataRoot: URL, indexes: [String: RaoLMIndex], nodes: [RaoLMPort.NodeIndex], out: URL, jobs: Int) throws {\n        try FileManager.default.createDirectory(at: out, withIntermediateDirectories: true)\n        var summaries: [RaoLMPort.ImportReport.SetSummary] = []\n        print(\"import-raolm · \\(dump.path) → \\(out.path)\")\n        print(\"  \\(\"set\".padding(toLength: 16, withPad: \" \", startingAt: 0)) records   steps     strand-positions without hits\")\n        for set in sets {\n            let outcomes = RaoLMPort.run(set: set, dump: dump, indexes: indexes, dataRoot: dataRoot, mode: .write(out), jobs: jobs) { note(\"import-raolm: \\($0)\") }\n            let report = RaoLMPort.SetReport(set: set, outcomes: outcomes)\n            summaries.append(RaoLMPort.ImportReport.SetSummary(report))\n            print(\"  \\(set.name.padding(toLength: 16, withPad: \" \", startingAt: 0)) \\(pad(report.records, 9)) \\(pad(report.steps, 9)) \\(pad(report.missingHits, 30)) → \\(out.appendingPathComponent(report.directory).path)/\")\n            for error in report.errors.prefix(5) { print(\"    ✗ \\(error)\") }\n        }\n        let report = RaoLMPort.ImportReport(createdAt: BenchFormat.wholeSecond(), dump: dump.path, dataRoot: dataRoot.path, nodes: nodes, sets: summaries)\n        let url = out.appendingPathComponent(RaoLMPort.ImportReport.fileName)\n        try JSONCoding.write(report, to: url)\n        print(\"import.json → \\(url.path)\")\n        print(\"  braid verify on these logs: \" + RaoLMPort.verifyChecks.sorted { $0.key < $1.key }.filter { $0.value.hasPrefix(\"skipped\") || $0.value.hasPrefix(\"refused\") }\n            .map { \"\\($0.key) \\($0.value.prefix(7))\" }.joined(separator: \"; \"))\n        if summaries.contains(where: { !$0.errors.isEmpty }) { throw BraidFailure.data(\"some records did not import\") }\n    }\n\n    /// The check report: every set's record-level checks and phase A.\n    struct CheckReport: Encodable {\n        var createdAt: Date\n        var dump: String\n        var dataRoot: String\n        var raolmReport: String?\n        var nodes: [RaoLMPort.NodeIndex]\n        var sets: [RaoLMPort.SetReport]\n        var phaseA: RaoLMPhaseA.Report?\n        var passes: [String: Bool]\n    }\n\n    func runCheck(sets: [RaoLMPort.RecordSet], dump: URL, index: RaoLMDumpIndex, dataRoot: URL, indexes: [String: RaoLMIndex], nodes: [RaoLMPort.NodeIndex],\n                  out: URL, jobs: Int) throws {\n        var reports: [RaoLMPort.SetReport] = []\n        var scored: [String: [String: RaoLMCheck.ScoredText]] = [:]\n        var lambda = 0.5\n        for set in sets {\n            let outcomes = RaoLMPort.run(set: set, dump: dump, indexes: indexes, dataRoot: dataRoot, mode: .check, jobs: jobs) { note(\"import-raolm: \\($0)\") }\n            reports.append(RaoLMPort.SetReport(set: set, outcomes: outcomes))\n            scored[set.name] = Dictionary(outcomes.compactMap { o in o.scored.map { (o.text.file, $0) } }, uniquingKeysWith: { first, _ in first })\n            note(\"import-raolm: \\(set.name) checked (\\(outcomes.count) records)\")\n        }\n        if let probe = try? RaoLMGeneration.load(from: dump.appendingPathComponent(sets[0].directory, isDirectory: true).appendingPathComponent(sets[0].texts[0].file)) {\n            lambda = Double(probe.params.lambda)\n        }\n        let reportURL = [dump.appendingPathComponent(\"trajectory.json\"), dataRoot.appendingPathComponent(\"bench/trajectory.json\")]\n            .first { FileManager.default.fileExists(atPath: $0.path) }\n        let raolm = try reportURL.map { try RaoLMTrajectoryReport.load(from: $0) }\n        let rule = raolm?.traceRule ?? .standard\n        var phaseA: RaoLMPhaseA.Report?\n        if let base = scored[\"base\"] {\n            var arms = scored\n            arms[\"base\"] = nil\n            phaseA = RaoLMPhaseA.run(index: index, base: base, arms: arms, report: raolm, rule: rule, lambda: lambda)\n        } else {\n            note(\"import-raolm: phase A needs the base pass; it is not among the sets checked\")\n        }\n\n        // The table.\n        print(\"port validation · \\(dump.path)\")\n        print(\"  RaoLM's report: \\(reportURL?.path ?? \"none found (looked at <dump>/trajectory.json and <dataRoot>/bench/trajectory.json)\")\")\n        for node in nodes {\n            print(\"  \\(node.name.padding(toLength: 8, withPad: \" \", startingAt: 0)) v\\(node.version) epoch \\(node.epoch)  index \\(node.sha256.prefix(12))  \\(node.entries) entries from \\(node.entryOffset), rows \\(node.rowOffset)..<\\(node.rowOffset + node.rowCount)\")\n        }\n        print(\"\")\n        print(\"(a) shares: share_t = w′_t·p_t(y)/p(y), w′ the gate renormalised over the open strands, p_t RaoLM's alone; tolerance 1e-5\")\n        print(\"    \\(\"set\".padding(toLength: 14, withPad: \" \", startingAt: 0)) records positions  values   max|Δ| alone  max|Δ| gate/lmProb/knn  max rel|Δp|  max|Δλ|   p_t from hits (n, max|Δ|)   verdict\")\n        for r in reports {\n            let s = r.shares\n            print(\"    \\(r.name.padding(toLength: 14, withPad: \" \", startingAt: 0)) \\(pad(r.records, 7)) \\(pad(s.positions, 9)) \\(pad(s.values, 8))  \\(sci(s.maxErrorAlone).padding(toLength: 12, withPad: \" \", startingAt: 0))  \\(sci(s.maxErrorLogged).padding(toLength: 21, withPad: \" \", startingAt: 0))  \\(sci(s.maxRelativeP).padding(toLength: 11, withPad: \" \", startingAt: 0))  \\(sci(s.maxLambdaError).padding(toLength: 8, withPad: \" \", startingAt: 0))  \\(pad(s.aloneFromHits, 8)) \\(sci(s.maxAloneFromHitsError).padding(toLength: 16, withPad: \" \", startingAt: 0))  \\(s.passes ? \"PASS\" : \"FAIL\")\")\n        }\n        let shares = reports.reduce(into: RaoLMCheck.Shares()) { $0.add($1.shares) }\n        if let worst = shares.worst { print(\"    largest: \\(worst.file) trace \\(worst.index) \\(worst.strand): recomputed \\(String(format: \"%.9f\", worst.recomputed)), logged \\(worst.logged)\") }\n        print(\"\")\n        print(\"(b) trace: Braid's TraceTracker on RaoLM's tokens and each strand's own hits over its index layout, against RaoLM's trajectory length and next\")\n        print(\"    \\(\"set\".padding(toLength: 14, withPad: \" \", startingAt: 0)) \\(\"strand\".padding(toLength: 8, withPad: \" \", startingAt: 0)) positions  matched   lacking hits  failed  after a lack (explained)\")\n        for r in reports {\n            for (name, t) in r.traces.strands.sorted(by: { $0.key < $1.key }) {\n                print(\"    \\(r.name.padding(toLength: 14, withPad: \" \", startingAt: 0)) \\(name.padding(toLength: 8, withPad: \" \", startingAt: 0)) \\(pad(t.positions, 9)) \\(pad(t.matched, 9)) \\(pad(t.missingHits, 12)) \\(pad(t.mismatches, 7)) \\(t.mismatchesAfterMissing) (\\(t.explained))\")\n            }\n        }\n        let traces = reports.reduce(into: RaoLMCheck.Traces()) { $0.add($1.traces) }\n        for m in traces.mismatches.prefix(12) {\n            print(\"    · \\(m.set) \\(m.file) \\(m.strand) trace \\(m.index): logged L=\\(m.loggedLength) next \\(m.loggedNext.map(String.init) ?? \"—\"), replayed L=\\(m.replayedLength) next \\(m.replayedNext.map(String.init) ?? \"—\")\"\n                + (m.afterMissingHits ? \"; the record lacks this strand's hits at trace\\(m.missingNear.count == 1 ? \"\" : \"s\") \\(m.missingNear.map(String.init).joined(separator: \", \"))\" : \"; every earlier hit present\"))\n        }\n        let mapping = reports.reduce(into: RaoLMCheck.Mapping()) { $0.add($1.mapping) }\n        print(\"    mapping: \\(mapping.hits) pooled hits → \\(mapping.outside) off their node, \\(mapping.valueMismatches) value and \\(mapping.keyMismatches) key mismatches against the node's index; \\(mapping.chains) logged chains, \\(mapping.chainMismatches) off the index; \\(mapping.traces) node traces, \\(mapping.traceMismatches) not the rule's\")\n        let verify = reports.reduce(into: RaoLMPort.VerifyTally()) { $0.add($1.verify) }\n        print(\"    braid verify on the imported sessions: \\(verify.logs) logs, \\(verify.issues) issues; trace \\(verify.traceMismatches) failed, \\(verify.traceUnreplayable) unreplayable; skipped: \\(verify.skipped.joined(separator: \", \"))\")\n        for row in phaseA?.armChains ?? [] {\n            print(\"    \\(row.arm.padding(toLength: 14, withPad: \" \", startingAt: 0)) logged chains equal the base pass's on \\(row.equal) of \\(row.positions) strand-positions (\\(row.records) records)\")\n        }\n        for issue in verify.firstIssues.prefix(5) { print(\"      ✗ \\(issue)\") }\n        print(\"\")\n        if let a = phaseA {\n            print(\"(c) phase A: Braid's trace-bench rules on RaoLM's traces (values from token \\(a.from); the chain after the last token by Braid's tracker)\")\n            print(\"    \\(\"rule\".padding(toLength: 26, withPad: \" \", startingAt: 0)) Braid  RaoLM  Braid's window\")\n            for (v, w) in zip(a.verdicts, a.braidWindowVerdicts) {\n                print(\"    \\(v.rule.padding(toLength: 26, withPad: \" \", startingAt: 0)) \\(word(v.braid))   \\(v.raolm.map(word) ?? \"—   \")   \\(word(w.braid))   \\(v.agrees ? \"equal\" : \"DIFFER\")\")\n                print(\"      Braid: \\(v.braidDetail)\")\n                if let detail = v.raolmDetail { print(\"      RaoLM: \\(detail)\") }\n            }\n            let r = a.readings\n            print(\"    readings against trajectory.json: \\(r.readings) text×strand; trace equal \\(r.traceEqual) (max |Δ| \\(sci(Double(r.maxTraceDifference)))), longest equal \\(r.longestEqual), wire longest equal \\(r.wireLongestEqual)\")\n            let g = a.regate\n            print(\"    regate under Braid's live gate (memory + lift over the commons) on \\(g.texts) told/source texts, \\(g.answerTokens) answer tokens:\")\n            print(\"      holder share: live \\(BenchFormat.num(g.live, 5)), shadow β4 \\(BenchFormat.num(g.shadow, 5)); RaoLM \\\"no agreement\\\" \\(BenchFormat.num(g.reference, 5)) → |Δ| \\(sci(Double(abs((g.live ?? 0) - (g.reference ?? 0))))) within ±\\(RaoLMPhaseA.regateTolerance): \\(g.passes ? \"PASS\" : \"FAIL\")\")\n            print(\"      live shares against the no-agreement arm's logged shares: max |Δ| \\(g.maxShareDifference.map(sci) ?? \"—\") over \\(g.comparedShares) values\")\n            print(\"      Gate.observe against RaoLM's logged memory: max |Δ| \\(sci(g.maxMemoryDifference)) over \\(g.memoryPositions) positions of \\(g.memoryTexts) base texts\")\n            print(\"    holder share of told and source answer tokens:\")\n            print(\"      \\(\"arm\".padding(toLength: 16, withPad: \" \", startingAt: 0)) RaoLM reported  from its records  |Δ|        not asked (reported / records)\")\n            for row in a.arms {\n                let delta = row.reported.flatMap { r in row.recomputed.map { sci(Double(abs(r - $0))) } } ?? \"—\"\n                print(\"      \\(row.arm.padding(toLength: 16, withPad: \" \", startingAt: 0)) \\(BenchFormat.num(row.reported, 6).padding(toLength: 15, withPad: \" \", startingAt: 0)) \\(BenchFormat.num(row.recomputed, 6).padding(toLength: 16, withPad: \" \", startingAt: 0)) \\(delta.padding(toLength: 10, withPad: \" \", startingAt: 0)) \\(BenchFormat.num(row.notAskedReported)) / \\(BenchFormat.num(row.notAskedRecomputed))\")\n            }\n            for arm in a.braidArms.prefix(1) {\n                print(\"      \\(\"Braid live gate\".padding(toLength: 16, withPad: \" \", startingAt: 0)) \\(BenchFormat.num(arm.live))  (\\(arm.set), \\(arm.texts) texts, \\(arm.answerTokens) tokens; memory only, regated)\")\n                print(\"      \\(\"Braid shadow β4\".padding(toLength: 16, withPad: \" \", startingAt: 0)) \\(BenchFormat.num(arm.shadow))  (over the regated memory and RaoLM's traces)\")\n            }\n            print(\"    \\(a.quoted)\")\n            print(\"\")\n        }\n        let passesA = reports.allSatisfy { $0.shares.passes }\n        let passesB = reports.allSatisfy { $0.traces.passes && $0.mapping.passes } && verify.issues == 0\n        let passesC = phaseA?.passes\n        let report = CheckReport(createdAt: BenchFormat.wholeSecond(), dump: dump.path, dataRoot: dataRoot.path, raolmReport: reportURL?.path, nodes: nodes,\n                                 sets: reports, phaseA: phaseA, passes: [\"a\": passesA, \"b\": passesB, \"c\": passesC ?? false])\n        try FileManager.default.createDirectory(at: out, withIntermediateDirectories: true)\n        let url = out.appendingPathComponent(\"check.json\")\n        try JSONCoding.write(report, to: url)\n        print(\"verdict: (a) \\(word(passesA))  (b) \\(word(passesB))  (c) \\(passesC.map(word) ?? \"not run\")\")\n        print(\"check.json → \\(url.path)\")\n        for r in reports where !r.errors.isEmpty { for error in r.errors.prefix(5) { print(\"  ✗ \\(error)\") } }\n        if !passesA || !passesB || passesC == false || reports.contains(where: { !$0.errors.isEmpty }) {\n            throw BraidFailure.data(\"the port validation fails\")\n        }\n    }\n\n    func pad(_ value: Int, _ width: Int) -> String { String(value).padding(toLength: width, withPad: \" \", startingAt: 0) }\n    func sci(_ value: Double) -> String { String(format: \"%.2e\", value) }\n    func word(_ passes: Bool) -> String { passes ? \"PASS\" : \"FAIL\" }\n}\n"},{"path":"Sources/BraidCLI/Commands/Sampler.swift","lines":52,"bytes":2532,"header":{"lines":[1,10],"what":[8,9],"pin":null,"in":null,"out":null},"marks":[],"first":1955,"scopes":[["E","Sampler",null,"",16,16,[16,13],52,null,-1,0,[]],["f","sampleAndNLL",["trunk","reed","tokenizer","prompt","tokens"],"static",24,24,[24,180],51,null,0,0]],"text":"//\n//  Sampler.swift\n//  BraidCLI\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The commons alone: a greedy sample from a prompt and the mean NLL on a few public-domain\n//        sentences, recorded in pack.json by `braid import --check` as the pack's reference numbers.\n//\n\nimport BraidKit\nimport Foundation\nimport MLX\n\nenum Sampler {\n    static let heldOut = [\n        \"It is a truth universally acknowledged, that a single man in possession of a good fortune, must be in want of a wife.\",\n        \"Call me Ishmael. Some years ago, never mind how long precisely, having little or no money in my purse, I thought I would sail about a little and see the watery part of the world.\",\n        \"It was the best of times, it was the worst of times, it was the age of wisdom, it was the age of foolishness.\",\n        \"Alice was beginning to get very tired of sitting by her sister on the bank, and of having nothing to do.\",\n    ]\n\n    static func sampleAndNLL(trunk: Trunk, reed: MLXReed, tokenizer: BraidTokenizer, prompt: String = \"The history of the city begins\", tokens: Int = 32) throws -> (String, Float) {\n        var ids: [Int32] = [tokenizer.eos] + tokenizer.encode(prompt)\n        var out = trunk.forward(tokens: MLXArray(ids, [1, ids.count]), state: nil, resets: nil)\n        var last = out.final[0, ids.count - 1]                                    // [D]\n        var generated: [Int32] = []\n        for _ in 0..<tokens {\n            let logits = reed.logits(array: last.reshaped([1, trunk.config.hiddenSize]))\n            let next = Int32(argMax(logits, axis: -1).item(Int32.self))\n            if next == tokenizer.eos { break }\n            generated.append(next)\n            ids.append(next)\n            out = trunk.step(token: MLXArray([next]), state: out.state, reset: nil)\n            last = out.final[0]\n        }\n        var total: Float = 0\n        var count = 0\n        for text in heldOut {\n            let seq: [Int32] = [tokenizer.eos] + tokenizer.encode(text)\n            let run = trunk.forward(tokens: MLXArray(seq, [1, seq.count]), state: nil, resets: nil)\n            let logits = reed.logits(array: run.final[0, 0 ..< seq.count - 1])\n            let targets = MLXArray(Array(seq[1...]))\n            let (loss, _) = MLXReed.tokenStats(logits: logits, targets: targets)\n            eval(loss)\n            total += loss.sum().item(Float.self)\n            count += seq.count - 1\n        }\n        return (tokenizer.decode(generated), total / Float(max(count, 1)))\n    }\n}\n"},{"path":"Sources/BraidCLI/Commands/SweepKey.swift","lines":81,"bytes":5766,"header":{"lines":[1,11],"what":[8,10],"pin":null,"in":null,"out":null},"marks":[],"first":1957,"scopes":[["S","SweepKeyCommand",null,"",17,17,[17,40],81,null,-1,0],["f","run",[],"",27,27,[27,22],80,null,0,0],["f","pad",["_","_","left"],"",65,65,[65,81],68,null,1,4],["f","f",["_"],"",69,69,[69,42],69,null,1,12]],"text":"//\n//  SweepKey.swift\n//  BraidCLI\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid bench sweep-key --thread <name>`: one Thread re-indexed under each key scheme; the\n//        document-identity probe and fact retrieval per scheme; a winner by the fixed rule and whether\n//        the +0.02 rule would ship it. Nothing changes a default.\n//\n\nimport ArgumentParser\nimport BraidKit\nimport Foundation\n\nstruct SweepKeyCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"sweep-key\", abstract: \"Re-index one Thread under each key scheme; probe document identity and fact retrieval per scheme.\")\n    @OptionGroup var workArea: WorkAreaOptions\n    @Option(help: \"The Thread to re-index (its trained blocks and snapshot).\") var thread: String\n    @Option(help: \"Comma-separated schemes (residual:N, pooled-state:L, state-delta:L).\") var arms: String?\n    @Option(help: \"Entries sampled for the document-identity probe.\") var sample: Int = 2000\n    @Option(help: \"Facts measured per arm (0 = all).\") var facts: Int = 0\n    @Option(help: \"Report path (default: bench/sweep-key/<stamp>.json in the work area).\") var report: String?\n    @Option(help: \"Random seed.\") var seed: UInt64 = 42\n\n    func run() throws {\n        guarded {\n            let area = try workArea.resolve()\n            let config = try workArea.config(in: area)\n            guard let packRecord = config.pack, let pack = try Packs.find(packRecord.sha256, in: area) else { throw BraidFailure.missing(\"braid.toml names no pack that is on disk\") }\n            let tokenizer = try BraidTokenizer(folder: pack.tokenizerFolder)\n            let scheme = KeyScheme(parsing: packRecord.keyScheme) ?? .residual(afterBlocks: pack.config.tapAfterBlocks)\n            let commons = try ThreadStore.commons(pack: pack, scheme: scheme)\n            let loaded = try ThreadStore.load(thread, in: area, pack: pack, commons: commons, tau: Float(config.index.tau))\n            let snapshot = try CorpusSnapshot.load(from: area.thread(thread).snapshot(hash: loaded.version.snapshotHash))\n            var options = KeySweepOptions()\n            if let arms {\n                options.arms = try arms.split(separator: \",\").map { text in\n                    guard let scheme = KeyScheme(parsing: String(text).trimmingCharacters(in: .whitespaces)) else { throw BraidFailure.usage(\"unknown key scheme \\(text)\") }\n                    return scheme\n                }\n            }\n            options.sample = sample\n            options.factLimit = facts\n            options.seed = seed\n            if let current = KeyScheme(parsing: packRecord.keyScheme) { options.defaultScheme = current }\n            // Facts come from the Thread's dataset node when it has one.\n            var factList: [Fact] = []\n            if case .dataset(let name, let node) = try CorpusSourceSpec(parsing: loaded.info.source) {\n                let root = DatasetsRoot.resolve(workArea: area.root)\n                let dataset = try BraidDataset.load(try DatasetsRoot.locate(name, root: root))\n                factList = try dataset.corpus(node: node).facts\n                note(\"facts: \\(factList.count) from dataset:\\(name)#\\(node)\")\n            } else {\n                note(\"facts: none (the Thread's source is not a dataset node); fact arms are skipped\")\n            }\n            let stamp = SessionLog.stamp()\n            let directory = area.bench.appendingPathComponent(\"sweep-key\", isDirectory: true).appendingPathComponent(stamp, isDirectory: true)\n            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)\n            let result = try KeySweep.run(thread: loaded, pack: pack, tokenizer: tokenizer, snapshot: snapshot, facts: factList, options: options, into: directory) { note($0) }\n            let reportURL = report.map { URL(fileURLWithPath: $0) } ?? area.bench.appendingPathComponent(\"sweep-key\", isDirectory: true).appendingPathComponent(\"\\(stamp).json\")\n            try JSONCoding.write(result, to: reportURL)\n            print(\"sweep-key: \\(result.thread) (\\(result.source)), \\(result.documents) documents, \\(result.factsLocated) facts located (\\(result.factsUnaligned) unaligned)\")\n            func pad(_ text: String, _ width: Int, left: Bool = false) -> String {\n                let fill = String(repeating: \" \", count: max(0, width - text.count))\n                return left ? text + fill : fill + text\n            }\n            func f(_ v: Float?) -> String { pad(v.map { String(format: \"%.3f\", $0) } ?? \"–\", 6) }\n            print([pad(\"scheme\", 16, left: true), pad(\"dims\", 5), pad(\"entr.\", 6), pad(\"build s\", 7), \" \", pad(\"doc\", 6), pad(\"part\", 6), \"  \", pad(\"p@1\", 6), pad(\"off@1\", 6), pad(\"ans@1\", 6), pad(\"mass\", 6), \"  \", pad(\"stem@1\", 6), pad(\"s.ans\", 6), \"  \", pad(\"para@1\", 6), pad(\"p.ans\", 6)].joined(separator: \" \"))\n            for arm in result.arms {\n                print([pad(arm.scheme, 16, left: true), pad(\"\\(arm.keyDims)\", 5), pad(\"\\(arm.entries)\", 6), pad(String(format: \"%.1f\", arm.buildSeconds), 7), \" \",\n                       f(arm.probe.sameDocument), f(arm.probe.samePartition), \"  \", f(arm.prompt?.partitionAt1), f(arm.prompt?.offsetAt1), f(arm.prompt?.answerAt1), f(arm.prompt?.meanAnswerMass), \"  \",\n                       f(arm.stem?.partitionAt1), f(arm.stem?.answerAt1), \"  \", f(arm.paraphrase?.partitionAt1), f(arm.paraphrase?.answerAt1)].joined(separator: \" \"))\n            }\n            print(\"default \\(result.defaultScheme); winner \\(result.winner ?? \"none\"); ships: \\(result.ships ? \"yes (+0.02 rule met; the owner decides)\" : \"no\")\")\n            for line in result.notes { print(\"note: \\(line)\") }\n            note(\"report → \\(reportURL.path)\")\n        }\n    }\n}\n"},{"path":"Sources/BraidCLI/Commands/Thread.swift","lines":137,"bytes":8220,"header":{"lines":[1,13],"what":[8,12],"pin":null,"in":null,"out":null},"marks":[],"first":1961,"scopes":[["S","ThreadCommand",null,"",19,19,[19,38],137,null,-1,0],["S","Create",null,"",23,23,[23,35],66,null,0,0],["f","run",[],"",49,49,[49,26],65,null,1,0],["S","Sync",null,"",68,68,[68,33],85,null,0,0],["f","run",[],"",75,75,[75,26],84,null,3,0],["S","Index",null,"",87,87,[87,34],104,null,0,0],["f","run",[],"",94,94,[94,26],103,null,5,0],["S","List",null,"",106,106,[106,33],121,null,0,0],["f","run",[],"",109,109,[109,26],120,null,7,0],["S","Show",null,"",123,123,[123,33],136,null,0,0],["f","run",[],"",127,127,[127,26],135,null,9,0]],"text":"//\n//  Thread.swift\n//  BraidCLI\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid thread create <name> --corpus <source>`: a Thread from a corpus source — snapshot,\n//        training and the provenance index on the pack's trunk — made live and attached to the\n//        braid in braid.toml. The flags become a ThreadRecipe that BraidKit's BraidEngine builds\n//        (the studio's new-Thread dialog runs the same path); `sync` and `index` are the engine's\n//        other two intents. `thread list` and `thread show` read the records.\n//\n\nimport ArgumentParser\nimport BraidKit\nimport Foundation\n\nstruct ThreadCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"thread\", abstract: \"Threads: create one from a corpus, list them, show one.\",\n                                                    subcommands: [Create.self, Sync.self, Index.self, List.self, Show.self], defaultSubcommand: List.self)\n\n    struct Create: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"create\", abstract: \"Snapshot a corpus, train and index a head for it behind the commons' trunk, make it live, attach it.\")\n        @OptionGroup var workArea: WorkAreaOptions\n        @Argument(help: \"The Thread's name (a lowercase handle).\")\n        var name: String\n        @Option(help: \"dataset:<name or path>#<node> · dir:<path> · aii:<aii>/<lane> · app:<aii>/<app>\")\n        var corpus: String\n        @Option(help: \"Only the first N documents of a dataset node (feeding order).\")\n        var limit: Int?\n        @Option(help: \"A display label (default: the name, capitalised).\")\n        var label: String?\n        @Option(help: \"The key scheme: residual:<n>, pooled-state:<layer>, state-delta:<layer> (default: braid.toml's).\")\n        var scheme: String?\n        @Flag(name: .customLong(\"no-attach\"), help: \"Do not add the Thread to [cluster] attach in braid.toml.\")\n        var noAttach = false\n        @Flag(name: .customLong(\"no-train\"), help: \"Index on the pack's own blocks 0..<cut, behind the commons' trunk, without training a head of the Thread's own.\")\n        var noTrain = false\n        @Option(help: \"Optimizer steps planned (default 1000 from the pack's blocks).\")\n        var steps: Int?\n        @Option(name: .customLong(\"batch\")) var batchSize: Int?\n        @Option(name: .customLong(\"seq-len\")) var seqLen: Int?\n        @Option(help: \"Train on every document but leave this fraction out of the index (the stitched bench's withheld set, e.g. 0.2).\")\n        var withhold: Double?\n        @Option(help: \"The training seed, which also draws the withheld documents (default 42).\")\n        var seed: UInt64?\n\n        func run() throws {\n            guarded {\n                let area = try workArea.resolve()\n                let config = try workArea.config(in: area)\n                guard let packRecord = config.pack, let pack = try Packs.find(packRecord.sha256, in: area) else { throw BraidFailure.missing(\"braid.toml names no pack that is on disk\") }\n                var recipe = try ThreadRecipe(name, corpus: corpus)\n                recipe.settings.limit = limit\n                recipe.settings.label = label\n                recipe.settings.key = try scheme.map(KeyScheme.parsed)\n                recipe.settings.training = noTrain ? .off : .on(steps: steps, batchSize: batchSize, seqLen: seqLen)\n                recipe.settings.withhold = withhold\n                recipe.settings.seed = seed\n                recipe.settings.attach = !noAttach\n                let engine = BraidEngine(area: area, config: config, pack: pack) { if let line = $0.line { note(line) } }\n                print(try engine.create(recipe).summary)\n            }\n        }\n    }\n\n    struct Sync: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"sync\", abstract: \"Read the Thread's source again; when its corpus changed, train on from the live blocks and index a new live version.\")\n        @OptionGroup var workArea: WorkAreaOptions\n        @Argument var name: String\n        @Flag(name: .customLong(\"no-train\"), help: \"Index the changed corpus with the live blocks, without training.\") var noTrain = false\n        @Option(help: \"Optimizer steps planned when training on (default 500).\") var steps: Int?\n\n        func run() throws {\n            guarded {\n                let area = try workArea.resolve()\n                let config = try workArea.config(in: area)\n                guard let packRecord = config.pack, let pack = try Packs.find(packRecord.sha256, in: area) else { throw BraidFailure.missing(\"braid.toml names no pack that is on disk\") }\n                let engine = BraidEngine(area: area, config: config, pack: pack) { if let line = $0.line { note(line) } }\n                let synced = try engine.sync(name, training: noTrain ? .off : .on(steps: steps))\n                if let outcome = synced.outcome { print(outcome.summary + \"  (\" + synced.diff.summary + \")\") } else { print(\"\\(name)  up to date\") }\n            }\n        }\n    }\n\n    struct Index: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"index\", abstract: \"Key the live version again under another key scheme or checkpoint policy, as a new live version.\")\n        @OptionGroup var workArea: WorkAreaOptions\n        @Argument var name: String\n        @Option(help: \"The key scheme: residual:<n>, pooled-state:<layer>, state-delta:<layer> (default: the live version's).\") var scheme: String?\n        @Flag(name: .customLong(\"checkpoint-every-partition\"), help: \"Write a state checkpoint at every partition boundary (for transfer), not only every 1,024 tokens.\") var everyPartition = false\n\n        func run() throws {\n            guarded {\n                let area = try workArea.resolve()\n                let config = try workArea.config(in: area)\n                guard let packRecord = config.pack, let pack = try Packs.find(packRecord.sha256, in: area) else { throw BraidFailure.missing(\"braid.toml names no pack that is on disk\") }\n                let engine = BraidEngine(area: area, config: config, pack: pack) { if let line = $0.line { note(line) } }\n                let outcome = try engine.rekey(name, key: try scheme.map(KeyScheme.parsed), checkpoints: everyPartition ? .atEveryPartition : CheckpointPolicy())\n                print(outcome.summary)\n            }\n        }\n    }\n\n    struct List: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"list\", abstract: \"Every Thread with its live version.\")\n        @OptionGroup var workArea: WorkAreaOptions\n        func run() throws {\n            guarded {\n                let area = try workArea.resolve()\n                let threads = try ThreadStore.list(in: area)\n                if threads.isEmpty { print(\"no threads in \\(area.threads.path); run braid thread create\"); return }\n                for info in threads {\n                    let live = try ThreadStore.live(area.thread(info.name))\n                    let version = live.map { \"v\\($0.version) \\($0.trained ? \"trained\" : \"base\") \\($0.keyScheme) index \\($0.indexSHA256.prefix(12)) memorised \\(String(format: \"%.0f%%\", $0.memorised * 100))\" } ?? \"no live version\"\n                    print(\"\\(info.name.padding(toLength: 14, withPad: \" \", startingAt: 0)) \\(info.source.padding(toLength: 34, withPad: \" \", startingAt: 0)) \\(version)\")\n                }\n            }\n        }\n    }\n\n    struct Show: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"show\", abstract: \"One Thread's record and live version.\")\n        @OptionGroup var workArea: WorkAreaOptions\n        @Argument var name: String\n        func run() throws {\n            guarded {\n                let area = try workArea.resolve()\n                let layout = area.thread(name)\n                let info = try ThreadStore.info(layout)\n                print(String(decoding: try JSONCoding.prettyEncoder().encode(info), as: UTF8.self))\n                if let live = try ThreadStore.live(layout) { print(String(decoding: try JSONCoding.prettyEncoder().encode(live), as: UTF8.self)) }\n            }\n        }\n    }\n}\n"},{"path":"Sources/BraidCLI/Commands/UI.swift","lines":59,"bytes":2991,"header":{"lines":[1,13],"what":[8,12],"pin":null,"in":null,"out":null},"marks":[],"first":1972,"scopes":[["S","UICommand",null,"",20,20,[20,39],59,null,-1,0],["f","run",[],"",35,35,[35,28],58,null,0,0]],"text":"//\n//  UI.swift\n//  BraidCLI\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid ui [--fixtures <dir>]`: the studio — the braid on one full-screen terminal screen,\n//        the Threads braid.toml attaches attached and the commons present, every token split by the\n//        strand that supplied it; 2 AII and 3 Doctor beside it. Bare `braid` in a terminal opens it\n//        too (BRAID_NO_UI=1 prints help instead). --fixtures (or BRAID_UI_FIXTURES) replays a\n//        recorded session with no MLX and no work area.\n//\n\nimport ArgumentParser\nimport BraidKit\nimport BraidStudio\nimport Foundation\n\nstruct UICommand: AsyncParsableCommand {\n    static let configuration = CommandConfiguration(\n        commandName: \"ui\",\n        abstract: \"Open the studio: the braid on one full-screen screen, its Threads attached, every token split by the strand that supplied it.\",\n        discussion: \"\"\"\n            Keys: ⏎ asks, / types a prompt, tab focuses a Thread and space attaches or detaches it, n makes a new Thread, R shows royalties or shares, ←→ walk the tokens, v verifies the spans, o replays a saved session, x takes a fact prompt, ? lists every key, q quits. 1–3 switch screens (Braid, AII, Doctor).\n            --fixtures (or BRAID_UI_FIXTURES) replays a recorded session with no MLX and no work area: Tests/BraidStudioTests/Fixtures/demo.\n            BRAID_COLOR=truecolor|256|16|none forces the colour depth; BRAID_ASCII=1 draws ASCII glyphs; BRAID_UI_THEME=terminal keeps the terminal's own background. What libraries print goes to <work area>/logs/studio.log.\n            \"\"\")\n\n    @OptionGroup var workArea: WorkAreaOptions\n\n    @Option(help: \"Replay a recorded session instead of using MLX (default: $BRAID_UI_FIXTURES).\")\n    var fixtures: String?\n\n    func run() async throws {\n        guard Studio.isInteractive else {\n            FileHandle.standardError.write(Data(\"braid: braid ui needs an interactive terminal\\n  run it directly, not through a pipe; BRAID_NO_UI=1 makes bare braid print help\\n\".utf8))\n            throw ArgumentParser.ExitCode(ExitCode.usage.rawValue)\n        }\n        var options = StudioOptions()\n        let fixturePath = fixtures ?? ProcessInfo.processInfo.environment[\"BRAID_UI_FIXTURES\"]\n        if let fixturePath, !fixturePath.isEmpty {\n            options.fixtures = URL(fileURLWithPath: (fixturePath as NSString).expandingTildeInPath, isDirectory: true)\n        } else {\n            do {\n                options.workArea = try workArea.resolve()\n            } catch {\n                options.workAreaProblem = \"\\(error)\"\n            }\n        }\n        do {\n            let code = try await Studio.launch(options)\n            if code != 0 { throw ArgumentParser.ExitCode(code) }\n        } catch let failure as BraidFailure {\n            FileHandle.standardError.write(Data(\"braid: \\(failure.description)\\n\".utf8))\n            throw ArgumentParser.ExitCode(failure.code.rawValue)\n        }\n    }\n}\n"},{"path":"Sources/BraidCLI/Commands/Verify.swift","lines":146,"bytes":9762,"header":{"lines":[1,16],"what":[8,15],"pin":null,"in":null,"out":null},"marks":[],"first":1974,"scopes":[["S","VerifyCommand",null,"",23,23,[23,38],146,null,-1,0],["f","run",[],"",38,38,[38,22],67,null,0,0],["f","imported",["_","url"],"",71,71,[71,76],85,[69,70],0,0],["f","braided",["_","url"],"",88,88,[88,75],145,[87,87],0,0]],"text":"//\n//  Verify.swift\n//  BraidCLI\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid verify <session.jsonl>`: replays the log — body hashes, share arithmetic, the gate's\n//        memory recursion, the shadow gate, the trace over each Thread's index layout, every verbatim\n//        span re-read from the Thread's snapshot (or the live lane with --live) — and, with --keys,\n//        recomputes every cited key from the nearest state checkpoint. Writes <id>.verify.json beside\n//        the log. Exit 0; 3 when a span no longer matches; 65 when the log's arithmetic fails.\n//        A log imported from RaoLM (`braid import-raolm`) needs no work area: its traces replay over\n//        the RaoLM indexes its import.json names, and the report says which checks it does not take\n//        (the memory recursion, the shadow β4, the spans).\n//\n\nimport ArgumentParser\nimport BraidKit\nimport Foundation\nimport MLX\n\nstruct VerifyCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"verify\", abstract: \"Replay a session log: hashes, arithmetic, traces, spans; --keys recomputes cited keys.\")\n\n    @OptionGroup var workArea: WorkAreaOptions\n    @Argument(help: \"The session log (sessions/<stamp>-<id>.jsonl).\")\n    var session: String\n    @Flag(help: \"Recompute every cited hit's key from the nearest state checkpoint (loads the trunk).\")\n    var keys = false\n    @Flag(name: .customLong(\"all-hits\"), help: \"With --keys: recompute every logged hit's key, not only the cited ones.\")\n    var allHits = false\n    @Flag(help: \"Re-read every span from the AII lane that holds its document, as it stands now (other documents from the snapshot).\")\n    var live = false\n    @Flag(name: .customLong(\"no-write\"), help: \"Do not write <id>.verify.json beside the log.\")\n    var noWrite = false\n\n    func run() throws {\n        guarded {\n            let url = URL(fileURLWithPath: (self.session as NSString).expandingTildeInPath)\n            let logged = try SessionReader.read(url)\n            let report = logged.header.source == RaoLMImport.source ? try imported(logged, url: url) : try braided(logged, url: url)\n            if !noWrite {\n                let out = url.deletingPathExtension().appendingPathExtension(\"verify.json\")\n                try JSONCoding.write(report, to: out)\n                note(\"verify: report → \\(out.path)\")\n            }\n            print(\"session \\(report.session): \\(report.generations) generation(s)\")\n            print(\"  arithmetic issues: \\(report.issues.filter { $0.check != \"trace\" && $0.check != \"keys\" }.count)\")\n            for check in report.traces {\n                print(\"  trace strand \\(check.strand): \\(check.positions) positions, \\(check.mismatches) mismatches\" + (check.unreplayable > 0 ? \", \\(check.unreplayable) unreplayable\" : \"\"))\n            }\n            if report.skipped.contains(\"spans\") {\n                print(\"  spans: not checked\")\n            } else {\n                print(\"  spans: \\(report.spansVerified) verified, \\(report.spansFailed) failed\")\n            }\n            if !report.skipped.isEmpty { print(\"  skipped: \\(report.skipped.joined(separator: \", \"))\") }\n            for span in report.spans where span.status != .verified { print(\"    ✗ \\(span.status.rawValue) \\(span.text.debugDescription) → \\(span.documentID.suffix(16)) p\\(span.partitionIndex)@\\(span.tokenOffset) \\(span.detail ?? \"\")\") }\n            for issue in report.issues.prefix(10) { print(\"  ✗ \\(issue)\") }\n            for noteLine in report.notes { print(\"  · \\(noteLine)\") }\n            print(report.status == .ok ? \"verified\" : \"FAILED\")\n            if report.status != .ok {\n                throw BraidFailure(report.spansFailed > 0 ? \"a span no longer matches its source\" : \"the log does not replay\", code: report.spansFailed > 0 ? .verifyMismatch : .data)\n            }\n        }\n    }\n\n    /// A log imported from RaoLM: no work area or pack (the tokenizer and the partitions are RaoLM's);\n    /// the traces replay over the RaoLM indexes the import.json beside the log names.\n    func imported(_ logged: LoggedSession, url: URL) throws -> VerifyReport {\n        if keys || live { throw BraidFailure.usage(\"--keys and --live do not apply to a log imported from RaoLM\", hint: \"its keys are RaoLM's and its partitions live in no AII lane\") }\n        var layouts: [String: IndexLayout] = [:]\n        var notes: [String] = []\n        if let (record, location) = RaoLMPort.ImportReport.find(near: url) {\n            layouts = try RaoLMPort.layouts(for: logged, report: record)\n            notes.append(\"raolm: index layouts found by sha under \\(record.dataRoot) (from \\(location.path))\")\n        } else {\n            notes.append(\"raolm: no import.json beside the log, so RaoLM's index layouts were not found and the trace is not replayed\")\n        }\n        var report = Verifier.verify(session: logged, name: url.lastPathComponent, layouts: { layouts[$0] }, reader: nil, tokenizer: nil)\n        report.notes += notes\n        if layouts.isEmpty { report.skipped.append(\"trace\") }\n        return report\n    }\n\n    /// A Braid log: the Threads in the work area, their snapshots (or live lanes) and the pack.\n    func braided(_ logged: LoggedSession, url: URL) throws -> VerifyReport {\n        let area = try workArea.resolve()\n        let config = try workArea.config(in: area)\n        guard let packRecord = config.pack, let pack = try Packs.find(packRecord.sha256, in: area) else { throw BraidFailure.missing(\"braid.toml names no pack that is on disk\") }\n        let tokenizer = try BraidTokenizer(folder: pack.tokenizerFolder)\n        // Every Thread the session names: its live index layout and its snapshot.\n        var layouts: [String: IndexLayout] = [:]\n        var snapshots: [CorpusSnapshot] = []\n        var loaded: [String: LoadedThread] = [:]\n        let names = Set(logged.header.threads.filter { !$0.commons }.map(\\.name) + logged.membership.filter { $0.kind == \"attach\" }.map(\\.thread.name))\n        let scheme = KeyScheme(parsing: packRecord.keyScheme) ?? .residual(afterBlocks: pack.config.tapAfterBlocks)\n        var commons: LocalNode? = nil                                                       // the trunk the Threads run behind, built once a Thread needs it\n        for name in names {\n            guard FileManager.default.fileExists(atPath: area.thread(name).record.path) else { note(\"verify: thread \\(name) is not in the work area; its spans and traces are skipped\"); continue }\n            if commons == nil { commons = try ThreadStore.commons(pack: pack, scheme: scheme) }\n            let thread = try ThreadStore.load(name, in: area, pack: pack, commons: commons!)\n            loaded[name] = thread\n            layouts[name] = thread.node.index?.layout\n            snapshots.append(try CorpusSnapshot.load(from: area.thread(name).snapshot(hash: thread.version.snapshotHash)))\n        }\n        let snapshotReader = SnapshotPartitionReader(snapshots: snapshots)\n        let liveReader = live ? LivePartitionReader(lanes: LivePartitionReader.lanes(for: logged), demoRoot: AIIDetect.demoRoot(), fallback: snapshotReader) : nil\n        var report = Verifier.verify(session: logged, name: url.lastPathComponent, layouts: { layouts[$0] }, reader: liveReader ?? snapshotReader, tokenizer: tokenizer)\n        if let liveReader {\n            report.notes.append(liveReader.used.isEmpty ? \"live: no span's document is held in an AII lane; spans were read from the snapshots\"\n                                                        : \"live: spans re-read from \\(liveReader.used.map(\\.description).sorted().joined(separator: \", \"))\")\n        }\n        if keys {\n            var worst: Float = 0\n            var checked = 0\n            for generation in logged.generations {\n                let strands = SessionReplay.strands(for: generation, session: logged)\n                for step in generation.steps where step.source == .gen {\n                    guard let records = step.threads else { continue }\n                    for (t, record) in records.enumerated() where t < strands.count && !strands[t].commons {\n                        guard let thread = loaded[strands[t].name], let index = thread.node.index else { continue }\n                        let snapshot = try CorpusSnapshot.load(from: area.thread(strands[t].name).snapshot(hash: thread.version.snapshotHash))\n                        let corpus = TokenizedCorpus(snapshot: snapshot, tokenizer: tokenizer, paragraphBreak: tokenizer.paragraphBreak, threadID: thread.info.threadID)\n                        for (rank, hit) in record.hits.enumerated() where allHits || (hit.value == step.token && rank < 3) {\n                            let entry = Int(hit.entry)\n                            let target = TokenPosition(row: Int(index.keyRow[entry]), offset: Int(index.keyOffset[entry]))\n                            let (replayed, _) = try Replay.key(at: target, index: index, corpus: corpus, trunk: thread.node.trunk, pack: pack)\n                            let cosine = (replayed * index.key(entry: entry)).sum()\n                            eval(cosine)\n                            worst = max(worst, 1 - cosine.item(Float.self))\n                            checked += 1\n                        }\n                    }\n                }\n            }\n            report.notes.append(String(format: \"keys: %d cited hits recomputed, worst 1 − cos %.2e\", checked, worst))\n            if worst > 1e-3 {\n                report.issues.append(ReplayIssue(generationID: \"-\", step: nil, strand: nil, check: \"keys\", detail: String(format: \"worst 1 − cos %.2e exceeds 1e-3\", worst)))\n                report.status = .failed\n            }\n        }\n        return report\n    }\n}\n"},{"path":"Sources/BraidCLI/Options.swift","lines":54,"bytes":2236,"header":{"lines":[1,10],"what":[8,9],"pin":null,"in":null,"out":null},"marks":[],"first":1978,"scopes":[["S","WorkAreaOptions",null,"",16,16,[16,42],34,null,-1,0],["f","resolve",[],"",20,20,[20,38],26,null,0,0],["f","config",["in"],"",28,28,[28,57],33,null,0,0],["f","guarded",["_"],"",37,37,[37,40],50,[36,36],-1,0],["S","ConformanceFailureBox",null,"",52,52,[52,61],52,null,-1,8],["f","note",["_"],"",54,54,[54,26],54,null,-1,8]],"text":"//\n//  Options.swift\n//  BraidCLI\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The options every command shares: the work area (BRAID_WORK_AREA, else the mounted T9,\n//        else refused unless named), and the failure mapping to sysexits so scripts can branch.\n//\n\nimport ArgumentParser\nimport BraidKit\nimport Foundation\n\nstruct WorkAreaOptions: ParsableArguments {\n    @Option(name: .customLong(\"work-area\"), help: \"Where Braid's data lives (default: BRAID_WORK_AREA, else /Volumes/T9/rao/projects/braid when the T9 is mounted).\")\n    var workAreaPath: String?\n\n    func resolve() throws -> WorkArea {\n        if let workAreaPath { return WorkArea(root: URL(fileURLWithPath: (workAreaPath as NSString).expandingTildeInPath, isDirectory: true)) }\n        guard let area = WorkArea.resolve() else {\n            throw BraidFailure.configuration(\"no work area: the T9 is not mounted\", hint: \"set BRAID_WORK_AREA or pass --work-area; Braid does not write to the internal disk unasked\")\n        }\n        return area\n    }\n\n    func config(in area: WorkArea) throws -> BraidConfig {\n        guard FileManager.default.fileExists(atPath: area.configFile.path) else {\n            throw BraidFailure.missing(\"no braid.toml in \\(area.root.path)\", hint: \"run braid init --base <pack or hf-id> first\")\n        }\n        return try BraidConfig.load(from: area.configFile)\n    }\n}\n\n/// Runs a command body, printing a BraidFailure and exiting with its code; other errors are internal.\nfunc guarded(_ body: () throws -> Void) {\n    do {\n        try body()\n    } catch let failure as BraidFailure {\n        FileHandle.standardError.write(Data(\"braid: \\(failure.description)\\n\".utf8))\n        exit(failure.code.rawValue)\n    } catch let failure as ConformanceFailureBox {\n        FileHandle.standardError.write(Data(\"braid: \\(failure.description)\\n\".utf8))\n        exit(ExitCode.data.rawValue)\n    } catch {\n        FileHandle.standardError.write(Data(\"braid: \\(error)\\n\".utf8))\n        exit(ExitCode.internalError.rawValue)\n    }\n}\n\nstruct ConformanceFailureBox: Error, CustomStringConvertible { var description: String }\n\nfunc note(_ text: String) { FileHandle.standardError.write(Data((text + \"\\n\").utf8)) }\n"}]};
